    blog_insaat_celik_imalat_title: 'Stahlbau-Schweißfertigung für die Bauindustrie | ArmaWeld',
    blog_insaat_celik_imalat_meta_desc: 'Stahlbau für die Bauindustrie: EN 1090 EXC2/EXC3, Tragsysteme, Werkstatt- und Baustellenschweißen.',
    blog_insaat_celik_imalat_og_title: 'Stahlbau-Schweißfertigung für die Bauindustrie',
    blog_insaat_celik_imalat_tag: 'Bau · Stahlbau',
    blog_insaat_celik_imalat_h1: 'Stahlbau-Schweißfertigung für die Bauindustrie',
    blog_insaat_celik_imalat_read: '7 Min. Lesezeit',
    blog_insaat_celik_imalat_author: 'ArmaWeld Engineering',
    blog_insaat_celik_imalat_breadcrumb3: 'Bauindustrie',
    blog_insaat_celik_imalat_s0: '<p>Die Bauindustrie ist einer der größten Verbraucher der Schweißfertigung. ArmaWeld fertigt EN 1090 EXC2/EXC3 zertifizierten Stahlbau aus Konya.</p>',
    blog_insaat_celik_imalat_s1: '<h2>1. Baustahlsorten</h2><ul><li>S235/S275: leichte Bauten</li><li>S355: industrielle Hauptträger</li><li>S420/S460: Hochleistungsprojekte</li></ul>',
    blog_insaat_celik_imalat_s2: '<h2>2. EN 1090 Ausführungsklassen</h2><table class="data-table"><thead><tr><th>Bautyp</th><th>EXC</th></tr></thead><tbody><tr><td>Landwirtschaft</td><td>EXC1</td></tr><tr><td>Industriegebäude</td><td>EXC2</td></tr><tr><td>Brücken, Kranbahnen</td><td>EXC3</td></tr><tr><td>Risikobauwerke</td><td>EXC4</td></tr></tbody></table>',
    blog_insaat_celik_imalat_s3: '<h2>3. Verbindungsdetails</h2><p>Geschweißt im Werk, geschraubt auf der Baustelle oder hybrid. Vorgespannte HV-Schrauben nach EN 14399.</p>',
    blog_insaat_celik_imalat_s4: '<h2>4. Typischer Projektablauf</h2><p>Konstruktion, Vorfertigung, Oberflächenvorbereitung Sa 2½, Lackieren oder Verzinken, Logistik und Montage. ArmaWeld liefert turnkey aus Konya.</p>',
    blog_insaat_celik_imalat_cta_h3: 'Angebot für Ihr Baustahlprojekt aus Konya',
    blog_insaat_celik_imalat_cta_p: 'Vorfertigung und Montage im EN 1090 EXC2/EXC3 zertifizierten Werk.',
    blog_insaat_celik_imalat_cta_btn: 'Angebot anfordern →',

    // 12
    blog_zirhli_arac_kaynak_title: 'Schweißen für gepanzerte Fahrzeuge und Verteidigungsplattformen | ArmaWeld',
    blog_zirhli_arac_kaynak_meta_desc: 'Schweißen gepanzerter Fahrzeuge: STANAG 4569, ARMOX/MARS Panzerstahl-Parameter und ballistische Akzeptanzkriterien.',
    blog_zirhli_arac_kaynak_og_title: 'Schweißen für gepanzerte Fahrzeuge und Verteidigungsplattformen',
    blog_zirhli_arac_kaynak_tag: 'Verteidigung · Gepanzerte Fahrzeuge',
    blog_zirhli_arac_kaynak_h1: 'Schweißen für gepanzerte Fahrzeuge und Verteidigungsplattformen',
    blog_zirhli_arac_kaynak_read: '9 Min. Lesezeit',
    blog_zirhli_arac_kaynak_author: 'ArmaWeld Engineering',
    blog_zirhli_arac_kaynak_breadcrumb3: 'Gepanzerte Fahrzeuge',
    blog_zirhli_arac_kaynak_s0: '<p>Bei der Fertigung gepanzerter Fahrzeuge sind Schweißnähte das schwächste Glied der ballistischen Schutzhülle. <strong>Schweißen gepanzerter Fahrzeuge</strong> umfasst Auswahl der Panzerstähle und enge Wärmeeintrags-Fenster.</p>',
    blog_zirhli_arac_kaynak_s1: '<h2>1. Panzerstahl-Auswahl</h2><table class="data-table"><thead><tr><th>Marke</th><th>Härte (HB)</th><th>STANAG</th></tr></thead><tbody><tr><td>ARMOX 500T</td><td>480–540</td><td>2–3</td></tr><tr><td>ARMOX 600T</td><td>570–640</td><td>3–4</td></tr><tr><td>MARS 240</td><td>440–500</td><td>2–3</td></tr><tr><td>SECURE 500</td><td>480–540</td><td>2–3</td></tr></tbody></table>',
    blog_zirhli_arac_kaynak_s2: '<h2>2. Schweißparameter</h2><ul><li>Max. Wärmeeintrag: 1,0–1,5 kJ/mm</li><li>Zwischenlage: 150–200°C</li><li>Vorwärmen: 100–150°C</li><li>Zusatz: austenitisch (E307, E309LMo)</li><li>H5 oder H4</li></ul>',
    blog_zirhli_arac_kaynak_s3: '<h2>3. Ballistische Verifikation</h2><p>Für hohe Bedrohungsstufen werden Testplatten mit scharfer Munition geschossen. Akzeptiert wird, wenn keine Risse oder Abplatzungen entstehen.</p>',
    blog_zirhli_arac_kaynak_s4: '<h2>4. ArmaWeld Verteidigungs-Erfahrung</h2><p>ArmaWeld fertigt aus Konya Subkomponenten und Module für gepanzerte Fahrzeuge unter EN ISO 3834-2.</p>',
    blog_zirhli_arac_kaynak_cta_h3: 'Angebot für Ihr Verteidigungsprojekt',
