  add('es', {

    blog_wpqr_title: 'Qué es WPQR: Cualificación de Procedimientos de Soldadura y EN ISO 15614 | ArmaWeld Blog',
    blog_wpqr_title_tag: 'Qué es WPQR: Cualificación de Procedimientos de Soldadura y EN ISO 15614 | ArmaWeld Blog',
    blog_wpqr_meta_desc: 'Qué es un WPQR (Registro de Cualificación de Procedimiento de Soldadura). Cómo cualificar un procedimiento de soldadura según EN ISO 15614-1 y 15614-2.',
    blog_wpqr_og_title: 'Qué es WPQR: Cualificación de Procedimientos de Soldadura',
    blog_wpqr_tag: 'Normas y Certificación',
    blog_wpqr_h1: 'Qué es WPQR: Cualificación de Procedimientos de Soldadura',
    blog_wpqr_read: '9 min de lectura',
    blog_wpqr_author: 'ArmaWeld Ingeniería',
    blog_wpqr_breadcrumb3: 'Qué es WPQR',
    blog_wpqr_s0: '<p>Un <strong>WPQR (Welding Procedure Qualification Record — Registro de Cualificación de Procedimiento de Soldadura)</strong> es un documento que certifica mediante resultados de ensayo que un procedimiento de soldadura alcanza las propiedades mecánicas requeridas. La WPS (Especificación de Procedimiento de Soldadura) solo define <em>cómo</em> soldar; el WPQR demuestra que <em>el procedimiento realmente alcanza</em> las propiedades deseadas.</p><div class="callout"><p><strong>Regla fundamental:</strong> Las empresas que fabrican bajo EN ISO 3834-2 y EN 1090-2 deben vincular cada WPS a un WPQR válido. Soldar con un procedimiento no cualificado no es aceptable.</p></div>',
    blog_wpqr_s1: '<h2>Diferencia entre WPS y WPQR</h2><table class="data-table"><thead><tr><th>Documento</th><th>Contenido</th><th>Propósito</th></tr></thead><tbody><tr><td>WPS</td><td>Corriente, tensión, gas, electrodo, secuencia de pasadas, precalentamiento</td><td>Instrucciones al soldador en taller</td></tr><tr><td>WPQR</td><td>Resultados de probeta: tracción, doblado, dureza, Charpy, macrografía</td><td>Demostrar la validez del procedimiento</td></tr><tr><td>Certificado</td><td>Firma de organismo de inspección independiente (TÜV, BV, DNV)</td><td>Aprobación de terceros</td></tr></tbody></table>',
    blog_wpqr_s2: '<h2>EN ISO 15614-1: Proceso de Cualificación para Acero</h2><ol><li>Elaborar pWPS (Especificación de Procedimiento Preliminar).</li><li>Soldar la probeta bajo condiciones de producción.</li><li>Ensayos no destructivos (END): VT, PT, UT o RT.</li><li>Ensayos destructivos: tracción, doblado, mapa de dureza, Charpy, macrografía.</li><li>Redactar y aprobar el WPQR: si es aceptable, la WPS queda formalmente cualificada.</li></ol>',
    blog_wpqr_s3: '<h2>Ensayos Requeridos</h2><table class="data-table"><thead><tr><th>Ensayo</th><th>Criterio de Aceptación</th><th>Norma</th></tr></thead><tbody><tr><td>Tracción</td><td>Rm ≥ resistencia mínima del metal base</td><td>EN ISO 4136</td></tr><tr><td>Doblado</td><td>4 probetas, 180°, sin grietas</td><td>EN ISO 5173</td></tr><tr><td>Charpy V</td><td>Energía media a temperatura WPS ≥ 27 J</td><td>EN ISO 9016</td></tr><tr><td>Dureza</td><td>HV10 — máx. 380 HV (S960QL: 450 HV)</td><td>EN ISO 9015-1</td></tr><tr><td>Macrografía</td><td>Sin grietas, poros ni falta de penetración</td><td>EN ISO 17639</td></tr></tbody></table>',
    blog_wpqr_s4: '<h2>Alcance de la Cualificación</h2><ul><li><strong>Grupo de material:</strong> Según CEN ISO/TR 15608</li><li><strong>Espesor:</strong> 0,5 a 2 veces el espesor de la probeta</li><li><strong>Diámetro (tubo):</strong> Todos los diámetros si diámetro de ensayo ≥ 25 mm</li></ul><div class="callout"><p><strong>Nota:</strong> Para soldadura de aluminio usar <strong>EN ISO 15614-2</strong>.</p></div>',
    blog_wpqr_s5: '<h2>Vigencia del WPQR</h2><p>Un WPQR cualificado bajo EN ISO 15614 tiene <strong>vigencia indefinida</strong>. Se requiere nueva cualificación si cambia el proceso de soldadura, el grupo de material o el espesor cualificado.</p><h2>Biblioteca WPS/WPQR de ArmaWeld</h2><p>ArmaWeld dispone de más de 80 registros de WPS y WPQR aprobados para acero al carbono (S235–S355), alta resistencia (S690QL, S700MC, S960QL), inoxidable (304L, 316L), aluminio y aceros resistentes al desgaste (HARDOX).</p>',
    blog_wpqr_cta_h3: '¿Necesita Soporte para WPS/WPQR?',
    blog_wpqr_cta_p: 'Contacte con nuestro equipo de ingeniería para elaboración y cualificación de procedimientos de soldadura.',
    blog_wpqr_cta_btn: 'Contactar →',

    blog_kaynak_hatalari_title: 'Defectos de Soldadura y Métodos de Reparación | ArmaWeld Blog',
    blog_kaynak_hatalari_title_tag: 'Defectos de Soldadura y Métodos de Reparación | ArmaWeld Blog',
    blog_kaynak_hatalari_meta_desc: 'Clasificación de defectos EN ISO 6520-1, criterios de aceptación EN ISO 5817, fisuración en frío, porosidad, falta de penetración y estrategias de reparación.',
    blog_kaynak_hatalari_og_title: 'Defectos de Soldadura y Métodos de Reparación',
    blog_kaynak_hatalari_tag: 'Calidad y END',
    blog_kaynak_hatalari_h1: 'Defectos de Soldadura y Métodos de Reparación',
    blog_kaynak_hatalari_read: '10 min de lectura',
    blog_kaynak_hatalari_author: 'ArmaWeld Ingeniería',
    blog_kaynak_hatalari_breadcrumb3: 'Defectos de Soldadura',
    blog_kaynak_hatalari_s0: '<p>Los defectos de soldadura afectan directamente la resistencia mecánica, la resistencia a la corrosión y la vida a fatiga. Los defectos se clasifican según <strong>EN ISO 6520-1</strong>; los criterios de aceptación se establecen en <strong>EN ISO 5817</strong>.</p>',
    blog_kaynak_hatalari_s1: '<h2>Clasificación de Defectos (EN ISO 6520-1)</h2><table class="data-table"><thead><tr><th>Grupo</th><th>Tipo</th><th>Ejemplo</th></tr></thead><tbody><tr><td>1</td><td>Grietas</td><td>Fisura en frío, fisura en caliente, desgarro laminar</td></tr><tr><td>2</td><td>Cavidades</td><td>Porosidad, sopladuras</td></tr><tr><td>3</td><td>Inclusiones sólidas</td><td>Inclusión de escoria, óxido</td></tr><tr><td>4</td><td>Falta de fusión/penetración</td><td>Falta de penetración, falta de fusión lateral</td></tr><tr><td>5</td><td>Imperfecciones de forma</td><td>Mordedura, relleno insuficiente, solape</td></tr><tr><td>6</td><td>Varios</td><td>Proyecciones, marcas de arco</td></tr></tbody></table>',
    blog_kaynak_hatalari_s2: '<h2>Niveles de Calidad EN ISO 5817</h2><ul><li><strong>Nivel B (alto):</strong> Estructuras con carga de fatiga, recipientes a presión.</li><li><strong>Nivel C (medio):</strong> Construcción metálica estándar, EN 1090 EXC2.</li><li><strong>Nivel D (bajo):</strong> Fabricación general estática.</li></ul>',
    blog_kaynak_hatalari_s3: '<h2>1. Fisuración en Frío</h2><p>Fisura de hidrógeno diferida que aparece horas o días después de soldar. Tres condiciones:</p><ol><li>Hidrógeno difusible</li><li>Alta tensión de tracción</li><li>Microestructura susceptible (martensita)</li></ol><div class="callout"><p><strong>Prevención:</strong> Precalentamiento + electrodo básico + consumible H5 + enfriamiento lento. Calcular según EN ISO 1011-2 Método B.</p></div>',
    blog_kaynak_hatalari_s4: '<h2>2. Fisuración en Caliente</h2><p>Se forma a alta temperatura durante la solidificación. Típica en aceros inoxidables, aluminio y aleaciones de níquel.</p><h2>3. Porosidad</h2><ul><li>Contaminación superficial (aceite, óxido, pintura, humedad)</li><li>Caudal de gas protector insuficiente</li><li>Ángulo de electrodo o velocidad incorrectos</li></ul>',
    blog_kaynak_hatalari_s5: '<h2>4. Falta de Penetración</h2><p>El metal de soldadura no alcanza la raíz. Detección: UT o RT obligatorio.</p><h2>5. Falta de Fusión Lateral</h2><p>Fusión insuficiente entre metal de aporte y metal base. Detectable por UT y RT.</p>',
    blog_kaynak_hatalari_s6: '<h2>Métodos END</h2><table class="data-table"><thead><tr><th>Método</th><th>Defectos Detectados</th><th>Norma</th></tr></thead><tbody><tr><td>VT (Visual)</td><td>Grieta superficial, porosidad, mordedura</td><td>EN ISO 17637</td></tr><tr><td>PT (Líquidos penetrantes)</td><td>Grieta abierta en superficie</td><td>EN ISO 3452</td></tr><tr><td>MT (Partículas magnéticas)</td><td>Grietas superficiales y subsuperficiales</td><td>EN ISO 17638</td></tr><tr><td>UT (Ultrasonidos)</td><td>Defectos internos, falta de penetración</td><td>EN ISO 17640</td></tr><tr><td>RT (Radiografía)</td><td>Defectos internos, porosidad, escoria</td><td>EN ISO 17636</td></tr></tbody></table><h2>Estrategia de Reparación</h2><ol><li>Delimitar el defecto por END</li><li>Eliminar: gouging, esmerilado o fresado</li><li>Verificar eliminación por PT/MT</li><li>Soldar la reparación con igual o menor aporte térmico</li><li>END final: VT + UT/RT</li></ol>',
    blog_kaynak_hatalari_cta_h3: 'Servicios de END y Auditoría de Calidad de Soldadura',
    blog_kaynak_hatalari_cta_p: 'Apoyo en análisis de defectos, planificación END y procedimientos de reparación.',
    blog_kaynak_hatalari_cta_btn: 'Contactar →',

    blog_on_isitma_title: 'Temperatura de Precalentamiento: EN ISO 1011-2 Método A y B | ArmaWeld Blog',
    blog_on_isitma_title_tag: 'Temperatura de Precalentamiento: EN ISO 1011-2 Método A y B | ArmaWeld Blog',
    blog_on_isitma_meta_desc: 'Cómo calcular la temperatura de precalentamiento. EN ISO 1011-2 Método A (CEV) y Método B (CET), ejemplo S690QL, métodos de aplicación práctica.',
    blog_on_isitma_og_title: 'Temperatura de Precalentamiento: EN ISO 1011-2 Método A y B',
    blog_on_isitma_tag: 'Parámetros de Soldadura',
    blog_on_isitma_h1: 'Temperatura de Precalentamiento: EN ISO 1011-2 Método A y B',
    blog_on_isitma_read: '8 min de lectura',
    blog_on_isitma_author: 'ArmaWeld Ingeniería',
    blog_on_isitma_breadcrumb3: 'Cálculo de Precalentamiento',
    blog_on_isitma_s0: '<p>Precalentar significa elevar el metal base a una temperatura determinada antes de soldar. Objetivo: reducir la velocidad de enfriamiento, minimizar el riesgo de <strong>fisuración en frío</strong> y evitar microestructuras duras.</p><div class="callout"><p><strong>Regla general:</strong> El precalentamiento es obligatorio para materiales con alto carbono equivalente, grandes espesores y bajas temperaturas ambientes.</p></div>',
    blog_on_isitma_s1: '<h2>EN ISO 1011-2: Dos Métodos</h2><ul><li><strong>Método A:</strong> Basado en CEV. Para aceros estructurales generales.</li><li><strong>Método B:</strong> Basado en CET. Diseñado para aceros de alta resistencia (S460–S960).</li></ul>',
    blog_on_isitma_s2: '<h2>Método A: Cálculo con CEV</h2><p><span class="tag-inline">CEV = C + Mn/6 + (Cr+Mo+V)/5 + (Ni+Cu)/15</span></p><table class="data-table"><thead><tr><th>Acero</th><th>CEV (típico)</th><th>Precalentamiento</th></tr></thead><tbody><tr><td>S235JR</td><td>0,35–0,40</td><td>Generalmente no necesario (≤30 mm)</td></tr><tr><td>S355J2+N</td><td>0,40–0,45</td><td>Recomendado en espesores ≥25 mm</td></tr><tr><td>S460M / S500MC</td><td>0,40–0,50</td><td>Típicamente 50–100°C</td></tr><tr><td>S690QL</td><td>0,55–0,65</td><td>100–150°C obligatorio</td></tr><tr><td>S960QL</td><td>0,65–0,82</td><td>150–200°C obligatorio</td></tr></tbody></table>',
    blog_on_isitma_s3: '<h2>Método B: CET y Fórmula Práctica</h2><p><span class="tag-inline">CET = C + (Mn+Mo)/10 + (Cr+Cu)/20 + Ni/40</span></p><p>Temperatura de precalentamiento T<sub>p</sub>:</p><p><span class="tag-inline">T<sub>p</sub> = 700·CET + 160·tanh(d/35) + 62·HD<sup>0,35</sup> + (53·CET - 32)·Q - 330</span></p>',
    blog_on_isitma_s4: '<h2>Ejemplo Práctico — S690QL</h2><p>Composición: C=0,16, Mn=1,50, Mo=0,40, Cr=0,30, Cu=0,20, Ni=0,40</p><ul><li>CET = <strong>0,385</strong></li><li>20 mm, consumible H5, 1,0 kJ/mm → T<sub>p</sub> = <strong>120,3°C</strong></li></ul><div class="callout"><p><strong>Resultado:</strong> El precalentamiento debe aplicarse a <strong>≥120°C</strong>.</p></div>',
    blog_on_isitma_s5: '<h2>Corrección por Temperatura Ambiente Baja</h2><ul><li>Ambiente +5°C a 0°C → añadir +25°C</li><li>Ambiente 0°C a −10°C → añadir +50°C</li><li>Por debajo de −10°C → aplazar la soldadura o habilitar refugio</li></ul><h2>Métodos de Precalentamiento</h2><ul><li><strong>Manta resistiva:</strong> Alta precisión, ideal para tubos y chapas gruesas.</li><li><strong>Inducción:</strong> Rápido, limpio. Preferido en líneas de producción.</li><li><strong>Soplete de gas:</strong> Común en soldadura en campo. Verificar con Tempilstick.</li></ul>',
    blog_on_isitma_s6: '<h2>Temperatura Entre Pasadas</h2><ul><li>Temperatura entre pasadas ≥ temperatura de precalentamiento</li><li>Temperatura entre pasadas ≤ recomendación del fabricante (≤220°C para S960QL)</li></ul>',
    blog_on_isitma_cta_h3: '¿Necesita Apoyo en el Cálculo de Precalentamiento?',
    blog_on_isitma_cta_p: 'Asistencia en cálculo de precalentamiento y elaboración de WPS para aceros de alta resistencia.',
    blog_on_isitma_cta_btn: 'Contactar →',

    blog_kaynak_distors_title: 'Distorsión en Soldadura: Prevención y Métodos de Corrección | ArmaWeld Blog',
    blog_kaynak_distors_title_tag: 'Distorsión en Soldadura: Prevención y Métodos de Corrección | ArmaWeld Blog',
    blog_kaynak_distors_meta_desc: 'Qué es la distorsión en soldadura, tipos, causas y estrategias de prevención. Minimizar la distorsión mediante diseño, preparación y secuencia de soldeo.',
    blog_kaynak_distors_og_title: 'Distorsión en Soldadura: Prevención y Métodos de Corrección',
    blog_kaynak_distors_tag: 'Ingeniería de Soldadura',
    blog_kaynak_distors_h1: 'Distorsión en Soldadura: Prevención y Métodos de Corrección',
    blog_kaynak_distors_read: '8 min de lectura',
    blog_kaynak_distors_author: 'ArmaWeld Ingeniería',
    blog_kaynak_distors_breadcrumb3: 'Distorsión en Soldadura',
    blog_kaynak_distors_s0: '<p>La distorsión en soldadura es consecuencia del calentamiento y enfriamiento no uniforme producido por el calor de soldadura.</p>',
    blog_kaynak_distors_s1: '<h2>Tipos de Distorsión</h2><table class="data-table"><thead><tr><th>Tipo</th><th>Descripción</th><th>Ubicación Típica</th></tr></thead><tbody><tr><td>Contracción Longitudinal</td><td>Acortamiento en dirección del cordón</td><td>Todas las soldaduras</td></tr><tr><td>Contracción Transversal</td><td>Estrechamiento perpendicular al cordón</td><td>Soldaduras a tope</td></tr><tr><td>Distorsión Angular</td><td>Apertura/cierre en forma de V en uniones en T</td><td>Soldaduras en ángulo</td></tr><tr><td>Pandeo</td><td>Ondulación en chapas delgadas</td><td>Chapa delgada (≤6 mm)</td></tr><tr><td>Flexión</td><td>Curvatura longitudinal de vigas</td><td>Viga I, perfil U</td></tr><tr><td>Torsión</td><td>Giro sobre el eje</td><td>Estructuras asimétricas</td></tr></tbody></table>',
    blog_kaynak_distors_s2: '<h2>Factores que Influyen</h2><ul><li><strong>Aporte térmico (Q):</strong> Mayor aporte → mayor distorsión</li><li><strong>Volumen de soldadura:</strong> Junta en V crea más distorsión que junta en X</li><li><strong>Coeficiente de dilatación:</strong> El acero inoxidable se dilata ~40% más que el acero al carbono</li></ul>',
    blog_kaynak_distors_s3: '<h2>Estrategias de Prevención</h2><h3>1. Fase de Diseño</h3><ul><li>Diseño de soldaduras simétricas (junta X, doble filete)</li><li>Minimizar metal de soldadura en exceso</li></ul><h3>2. Fase de Preparación</h3><ul><li><strong>Precamber:</strong> Preformar la pieza en dirección opuesta a la distorsión esperada</li><li><strong>Puntos de soldeo:</strong> Espaciado correcto (50–150 mm)</li></ul><h3>3. Durante el Soldeo</h3><ul><li><strong>Soldeo por saltos:</strong> Alternar entre distintas zonas</li><li><strong>Soldeo hacia atrás:</strong> Cada pasada en sentido contrario</li><li><strong>Bajo aporte térmico:</strong> Electrodo pequeño, mayor velocidad</li></ul>',
    blog_kaynak_distors_s4: '<h2>Estimación y Corrección</h2><p>Estimación de contracción transversal: <span class="tag-inline">ΔS ≈ 0,2 × A<sub>w</sub> / t</span></p><h2>Corrección de Distorsión</h2><ul><li><strong>Corrección mecánica:</strong> Prensa o martillo (solo chapas delgadas)</li><li><strong>Enderezado por llama:</strong> Calentar a ~600–650°C, enfriar controlado</li></ul><div class="callout"><p><strong>El enderezado en caliente está PROHIBIDO para HARDOX y S960QL.</strong> Por encima de 200°C la dureza del material se degrada irreversiblemente. Usar únicamente utillaje y precamber.</p></div>',
    blog_kaynak_distors_cta_h3: 'Soporte de Ingeniería para Control de Distorsión',
    blog_kaynak_distors_cta_p: 'Contacte con nuestro equipo para optimización de secuencias de soldeo y estrategias de prevención.',
    blog_kaynak_distors_cta_btn: 'Contactar →',

    blog_kaynak_pozis_title: 'Posiciones de Soldadura: EN ISO 6947 y AWS A3.0 | ArmaWeld Blog',
    blog_kaynak_pozis_title_tag: 'Posiciones de Soldadura: EN ISO 6947 y AWS A3.0 | ArmaWeld Blog',
    blog_kaynak_pozis_meta_desc: 'Posiciones de soldadura PA–PG y 1G–6G, EN ISO 6947 vs AWS A3.0, rango de cualificación EN ISO 9606 y ajuste de parámetros por posición.',
    blog_kaynak_pozis_og_title: 'Posiciones de Soldadura: EN ISO 6947 y AWS A3.0',
    blog_kaynak_pozis_tag: 'Ingeniería de Soldadura',
    blog_kaynak_pozis_h1: 'Posiciones de Soldadura: EN ISO 6947 y AWS A3.0',
    blog_kaynak_pozis_read: '7 min de lectura',
    blog_kaynak_pozis_author: 'ArmaWeld Ingeniería',
    blog_kaynak_pozis_breadcrumb3: 'Posiciones de Soldadura',
    blog_kaynak_pozis_s0: '<p>La posición de soldadura describe la orientación del cordón respecto a la gravedad.</p><div class="callout"><p><strong>EN ISO 6947</strong> define posiciones para placa y tubería con terminología armonizada. En EE. UU., AWS A3.0 usa códigos diferentes (1G, 2G, 3G, 4G, 5G, 6G).</p></div>',
    blog_kaynak_pozis_s1: '<h2>Posiciones en Placa</h2><table class="data-table"><thead><tr><th>Posición</th><th>Descripción</th><th>Equiv. AWS</th></tr></thead><tbody><tr><td>PA</td><td>Cornisa (horizontal, cordón en superficie superior)</td><td>1G / 1F</td></tr><tr><td>PB</td><td>Ángulo horizontal (unión T, cordón a 45°)</td><td>2F</td></tr><tr><td>PC</td><td>Tope horizontal (pieza vertical, cordón horizontal)</td><td>2G</td></tr><tr><td>PD</td><td>Ángulo en techo (unión T mirando hacia arriba)</td><td>4F</td></tr><tr><td>PE</td><td>Bajo techo (pieza horizontal, cordón desde abajo)</td><td>4G</td></tr><tr><td>PF</td><td>Vertical ascendente</td><td>3G arriba</td></tr><tr><td>PG</td><td>Vertical descendente</td><td>3G abajo</td></tr></tbody></table>',
    blog_kaynak_pozis_s2: '<h2>Posiciones en Tubo</h2><table class="data-table"><thead><tr><th>Posición</th><th>Descripción</th><th>Equiv. AWS</th></tr></thead><tbody><tr><td>PA (tubo)</td><td>Tubo horizontal, giratorio</td><td>1G tubo</td></tr><tr><td>PC (tubo)</td><td>Tubo vertical, fijo</td><td>2G tubo</td></tr><tr><td>H-L045</td><td>Tubo a 45°, fijo — posición combinada</td><td>6G</td></tr><tr><td>PF (tubo)</td><td>Tubo horizontal fijo, cordón ascendente</td><td>5G arriba</td></tr><tr><td>PG (tubo)</td><td>Tubo horizontal fijo, cordón descendente</td><td>5G abajo</td></tr></tbody></table>',
    blog_kaynak_pozis_s3: '<h2>Ranking de Dificultad</h2><ol><li>PA / PB — gravedad favorece el baño</li><li>PC — fluidez del baño difícil</li><li>PF — difícil evitar caída del baño</li><li>PG — baño sobre escoria, riesgo de falta de fusión</li><li>PD — bajo techo, gravedad contraria</li><li>PE — la más difícil</li><li>H-L045 (6G) — combina todas las características</li></ol>',
    blog_kaynak_pozis_s4: '<h2>Ajuste de Parámetros por Posición</h2><table class="data-table"><thead><tr><th>Posición</th><th>Ajuste de Corriente</th><th>Transferencia MIG/MAG típica</th></tr></thead><tbody><tr><td>PA</td><td>Máximo (referencia)</td><td>Spray, Pulsado</td></tr><tr><td>PF</td><td>−20 a −25%</td><td>Cortocircuito, Pulsado</td></tr><tr><td>PG</td><td>+5 a +10%</td><td>Cortocircuito</td></tr><tr><td>PE</td><td>−25 a −30%</td><td>Cortocircuito, FCAW</td></tr></tbody></table>',
    blog_kaynak_pozis_s5: '<h2>Rango de Cualificación EN ISO 9606</h2><ul><li><strong>Examen posición PE</strong> — cubre PA, PB, PC, PD, PE</li><li><strong>Examen posición PF</strong> — cubre PA, PB, PF</li><li><strong>Examen posición H-L045</strong> — cubre todas las posiciones fijas en tubo</li></ul><div class="callout"><p><strong>Recomendación:</strong> El examen H-L045 (6G) da la cualificación más amplia. Es estándar para soldadores de tuberías, recipientes a presión y construcción naval.</p></div>',
    blog_kaynak_pozis_cta_h3: 'Exámenes de Soldadores y Apoyo en WPS',
    blog_kaynak_pozis_cta_p: 'Apoyo en exámenes EN ISO 9606 y elaboración de WPS.',
    blog_kaynak_pozis_cta_btn: 'Contactar →',

    blog_kaynak_sembol_title: 'Símbolos de Soldadura: EN ISO 2553 y AWS A2.4 | ArmaWeld Blog',
    blog_kaynak_sembol_title_tag: 'Símbolos de Soldadura: EN ISO 2553 y AWS A2.4 | ArmaWeld Blog',
    blog_kaynak_sembol_meta_desc: 'Símbolos de soldadura EN ISO 2553 y AWS A2.4, símbolos básicos, información dimensional, ejemplos prácticos y guía de lectura.',
    blog_kaynak_sembol_og_title: 'Símbolos de Soldadura: EN ISO 2553 y AWS A2.4',
    blog_kaynak_sembol_tag: 'Ingeniería de Soldadura',
    blog_kaynak_sembol_h1: 'Símbolos de Soldadura: EN ISO 2553 y AWS A2.4',
    blog_kaynak_sembol_read: '9 min de lectura',
    blog_kaynak_sembol_author: 'ArmaWeld Ingeniería',
    blog_kaynak_sembol_breadcrumb3: 'Símbolos de Soldadura',
    blog_kaynak_sembol_s0: '<p>La simbolización de soldadura es el sistema de símbolos normalizados que define las uniones soldadas en planos técnicos. En Europa se usa <strong>EN ISO 2553</strong>; en EE. UU., <strong>AWS A2.4</strong>.</p>',
    blog_kaynak_sembol_s1: '<h2>Estructura del Símbolo</h2><ol><li><strong>Línea de referencia:</strong> Línea horizontal principal</li><li><strong>Flecha:</strong> Indica el punto de unión</li><li><strong>Símbolo básico:</strong> Forma geométrica que indica el tipo de soldadura</li><li><strong>Símbolos complementarios:</strong> Acabado superficial, soldadura perimetral, soldadura en obra, etc.</li></ol>',
    blog_kaynak_sembol_s2: '<h2>Símbolos Básicos de Soldadura</h2><table class="data-table"><thead><tr><th>Símbolo</th><th>Significado</th><th>Descripción</th></tr></thead><tbody><tr><td>I</td><td>Soldadura en I</td><td>Sin apertura de raíz, chapa delgada</td></tr><tr><td>V</td><td>Soldadura en V</td><td>Preparación en V por un lado</td></tr><tr><td>X (doble V)</td><td>Doble V</td><td>Chapa gruesa, simétrico</td></tr><tr><td>U</td><td>Soldadura en U</td><td>Chapa muy gruesa, poco metal</td></tr><tr><td>K (triángulo)</td><td>Soldadura en ángulo</td><td>Unión T, cordón de relleno</td></tr></tbody></table>',
    blog_kaynak_sembol_s3: '<h2>Colocación del Símbolo: EN ISO 2553</h2><ul><li><strong>Sistema A (europeo):</strong> Símbolo del lado flecha encima de la línea de referencia</li><li><strong>Sistema B (ISO):</strong> Línea de referencia doble — preferida en proyectos internacionales</li></ul><div class="callout"><p><strong>Diferencia con AWS A2.4:</strong> En AWS el símbolo del lado flecha siempre se escribe debajo de la línea de referencia. No mezclar los dos estándares en un mismo plano.</p></div>',
    blog_kaynak_sembol_s4: '<h2>Información Dimensional</h2><ul><li><strong>a:</strong> Garganta (soldadura en ángulo)</li><li><strong>z:</strong> Cateto (soldadura en ángulo)</li><li><strong>s:</strong> Profundidad de penetración (soldadura a tope)</li><li><strong>L:</strong> Longitud del cordón (soldadura intermitente)</li><li><strong>e:</strong> Distancia entre cordones</li><li><strong>n:</strong> Número de cordones</li></ul>',
    blog_kaynak_sembol_s5: '<h2>Ejemplos Prácticos</h2><h3>Ejemplo 1: Doble Soldadura en Ángulo en Unión T</h3><p>Símbolo: <span class="tag-inline">a5 ▽ ⌒</span> — garganta 5 mm, continuo, ambos lados.</p><h3>Ejemplo 2: Soldadura en Ángulo Intermitente</h3><p>Símbolo: <span class="tag-inline">a4 ▽ 6×50 (100)</span> — garganta 4 mm, 6 cordones de 50 mm, paso 100 mm.</p>',
    blog_kaynak_sembol_s6: '<h2>Soldadura Perimetral y en Obra</h2><ul><li><strong>Círculo (○):</strong> Soldadura perimetral (todo el contorno)</li><li><strong>Bandera (▶):</strong> Soldadura en obra — a ejecutar en el lugar de montaje</li></ul>',
    blog_kaynak_sembol_s7: '<h2>Acabado Superficial y Referencias en la Cola</h2><ul><li><strong>Línea plana (—):</strong> Superficie plana (esmerilado)</li><li><strong>Arco cóncavo (∪):</strong> Superficie cóncava</li><li><strong>Arco convexo (∩):</strong> Superficie convexa</li></ul><div class="callout"><p><strong>Buena práctica:</strong> Indicar en la cola el número de proceso, número de WPS y nivel de calidad. Ejemplo: <em>135 / WPS-022 / EN ISO 5817-B</em></p></div>',
    blog_kaynak_sembol_cta_h3: 'Apoyo en Planos Técnicos y WPS',
    blog_kaynak_sembol_cta_p: 'Soporte de ingeniería en simbolización de soldadura y documentación técnica.',
    blog_kaynak_sembol_cta_btn: 'Contactar →',

    blog_basincli_kap_title: 'Fabricación de Recipientes a Presión: PED 2014/68/UE y EN 13445 | ArmaWeld Blog',
    blog_basincli_kap_title_tag: 'Fabricación de Recipientes a Presión: PED 2014/68/UE y EN 13445 | ArmaWeld Blog',
    blog_basincli_kap_meta_desc: 'Fabricación de recipientes a presión, Directiva PED 2014/68/UE, EN 13445, clasificación de categorías, evaluación modular, marcado CE.',
    blog_basincli_kap_og_title: 'Fabricación de Recipientes a Presión: PED 2014/68/UE y EN 13445',
    blog_basincli_kap_tag: 'Recipientes a Presión',
    blog_basincli_kap_h1: 'Fabricación de Recipientes a Presión: PED 2014/68/UE y EN 13445',
    blog_basincli_kap_read: '10 min de lectura',
    blog_basincli_kap_author: 'ArmaWeld Ingeniería',
    blog_basincli_kap_breadcrumb3: 'Recipientes a Presión',
    blog_basincli_kap_s0: '<p>Un recipiente a presión es un envase cerrado que contiene gas o líquido a una presión diferente de la atmósfera. Todo equipo a presión comercializado en la UE debe llevar el marcado CE conforme a la <strong>Directiva de Equipos a Presión 2014/68/UE (PED)</strong>.</p>',
    blog_basincli_kap_s1: '<h2>Alcance de la Directiva</h2><ul><li>Equipos con presión máxima admisible PS > 0,5 bar</li><li>Tuberías, calderas, depósitos, intercambiadores de calor</li></ul>',
    blog_basincli_kap_s2: '<h2>Clasificación de Fluidos</h2><table class="data-table"><thead><tr><th>Grupo</th><th>Definición</th><th>Ejemplos</th></tr></thead><tbody><tr><td>Grupo 1</td><td>Fluidos peligrosos (inflamables, tóxicos, oxidantes)</td><td>Gas natural, propano, cloro, oxígeno</td></tr><tr><td>Grupo 2</td><td>Todos los demás fluidos</td><td>Aire, nitrógeno, agua, aceite hidráulico</td></tr></tbody></table>',
    blog_basincli_kap_s3: '<h2>Determinación de Categoría</h2><table class="data-table"><thead><tr><th>Categoría</th><th>Condición (Grupo 2 gas)</th><th>Módulos</th></tr></thead><tbody><tr><td>SEP</td><td>PS·V ≤ 200 bar·L</td><td>Buena Práctica de Ingeniería</td></tr><tr><td>I</td><td>200 &lt; PS·V ≤ 1000</td><td>A</td></tr><tr><td>II</td><td>1000 &lt; PS·V ≤ 3000</td><td>A2, D1, E1</td></tr><tr><td>III</td><td>3000 &lt; PS·V ≤ 10000</td><td>B+C2, B+D, H</td></tr><tr><td>IV</td><td>PS·V > 10000</td><td>B+D, G, H1</td></tr></tbody></table>',
    blog_basincli_kap_s4: '<h2>Norma de Cálculo: EN 13445</h2><ul><li><strong>EN 13445-1:</strong> Generalidades</li><li><strong>EN 13445-2:</strong> Materiales</li><li><strong>EN 13445-3:</strong> Cálculo de diseño</li><li><strong>EN 13445-4:</strong> Fabricación (soldadura)</li><li><strong>EN 13445-5:</strong> Inspección y ensayos</li></ul>',
    blog_basincli_kap_s5: '<h2>Requisitos de Soldadura</h2><ol><li>WPS cualificada (EN ISO 15614-1) — verificada por organismo notificado</li><li>Soldador certificado (EN ISO 9606)</li><li>Gestión de calidad en soldadura (EN ISO 3834-2)</li><li>END: 100% VT, 10–100% UT/RT</li><li>Prueba hidrostática: 1,43 × presión de diseño</li></ol>',
    blog_basincli_kap_s6: '<h2>Etapas de Fabricación</h2><ol><li>Cálculo de diseño (EN 13445-3)</li><li>Aprobación de materiales: certificado 3.1/3.2</li><li>Corte y conformado</li><li>Soldadura: WPS cualificada, precalentamiento, END</li><li>Tratamiento térmico PWHT</li><li>Inspección END</li><li>Prueba hidrostática: 1,43 × PS</li><li>Marcado CE + placa de características</li></ol><div class="callout"><p><strong>Alcance ArmaWeld:</strong> ArmaWeld fabrica recipientes a presión de categorías I, II y III con certificación EN ISO 3834-2.</p></div>',
    blog_basincli_kap_s7: '<h2>Errores Frecuentes</h2><ul><li>Fabricar sin EN ISO 3834-2 incluso en categoría SEP</li><li>Usar acero sin certificado 3.1</li><li>Soldar con WPS no cualificada</li><li>No purgar aire antes de la prueba hidrostática</li><li>Registros de trazabilidad incompletos</li></ul>',
    blog_basincli_kap_cta_h3: 'Fabricación de Recipientes a Presión conformes a PED',
    blog_basincli_kap_cta_p: 'Contacte para apoyo en diseño y fabricación según EN 13445 y PED 2014/68/UE.',
    blog_basincli_kap_cta_btn: 'Contactar →',

    blog_demiryolu_kaynak_title: 'Norma de Soldadura Ferroviaria EN 15085: Vagones y Bogies | ArmaWeld Blog',
    blog_demiryolu_kaynak_title_tag: 'Norma de Soldadura Ferroviaria EN 15085: Vagones y Bogies | ArmaWeld Blog',
    blog_demiryolu_kaynak_meta_desc: 'Norma de soldadura ferroviaria EN 15085, niveles de certificación CL1–CL4, fabricación de vagones soldados, producción de bogies, documentos ECWS.',
    blog_demiryolu_kaynak_og_title: 'Norma de Soldadura Ferroviaria EN 15085: Vagones y Bogies',
    blog_demiryolu_kaynak_tag: 'Ferroviario y Transporte',
    blog_demiryolu_kaynak_h1: 'Norma de Soldadura Ferroviaria EN 15085: Vagones y Bogies',
    blog_demiryolu_kaynak_read: '9 min de lectura',
    blog_demiryolu_kaynak_author: 'ArmaWeld Ingeniería',
    blog_demiryolu_kaynak_breadcrumb3: 'EN 15085 Ferroviario',
    blog_demiryolu_kaynak_s0: '<p>En el sector ferroviario la calidad de la soldadura se rige por la <strong>serie de normas EN 15085</strong>, adaptación ferroviaria de ISO 3834-2, obligatoria en la UE desde 2008.</p>',
    blog_demiryolu_kaynak_s1: '<h2>Las Cinco Partes de EN 15085</h2><table class="data-table"><thead><tr><th>Parte</th><th>Alcance</th></tr></thead><tbody><tr><td>EN 15085-1</td><td>Alcance general y estructura</td></tr><tr><td>EN 15085-2</td><td>Requisitos de certificación del fabricante (CL1–CL4)</td></tr><tr><td>EN 15085-3</td><td>Requisitos de diseño (clases de rendimiento CP A, B, C, D)</td></tr><tr><td>EN 15085-4</td><td>Requisitos de fabricación</td></tr><tr><td>EN 15085-5</td><td>Inspección y ensayo</td></tr></tbody></table>',
    blog_demiryolu_kaynak_s2: '<h2>Niveles de Certificación (CL)</h2><table class="data-table"><thead><tr><th>Nivel</th><th>Alcance</th><th>Componentes</th></tr></thead><tbody><tr><td>CL1</td><td>Todas las categorías (CP A, B, C, D)</td><td>Bogie, eje, freno, enganche</td></tr><tr><td>CL2</td><td>CP B, C, D</td><td>Estructura del vagón, marco de puerta</td></tr><tr><td>CL3</td><td>CP C, D</td><td>Mobiliario interior, pasamanos</td></tr><tr><td>CL4</td><td>Solo CP D</td><td>Componentes decorativos</td></tr></tbody></table>',
    blog_demiryolu_kaynak_s3: '<h2>Clases de Rendimiento (CP)</h2><ul><li><strong>CP A:</strong> Altamente crítico para la seguridad, carga dinámica, riesgo de muerte</li><li><strong>CP B:</strong> Media-alta criticidad, carga dinámica</li><li><strong>CP C:</strong> Criticidad media, carga estática o dinámica baja</li><li><strong>CP D:</strong> Baja criticidad de seguridad, decorativo</li></ul>',
    blog_demiryolu_kaynak_s4: '<h2>Proceso de Certificación EN 15085-2</h2><ol><li>Solicitud a organismo reconocido (TÜV SÜD, Lloyd\'s, Bureau Veritas)</li><li>Auditoría inicial: ISO 3834-2 + ISO 9001 + EN 15085</li><li>Biblioteca de WPS cualificadas</li><li>Soldadores certificados: EN ISO 9606 + módulo EN 15085</li><li>Coordinador Europeo (ECWS): Ingeniero nivel IWE/IWT</li><li>Vigencia certificado: 3 años, auditorías intermedias cada 12 meses</li></ol>',
    blog_demiryolu_kaynak_s5: '<h2>Materiales Específicos del Sector Ferroviario</h2><table class="data-table"><thead><tr><th>Material</th><th>Uso Típico</th><th>Propiedad</th></tr></thead><tbody><tr><td>S355J2W</td><td>Revestimiento exterior del vagón</td><td>Resistencia a la corrosión atmosférica</td></tr><tr><td>S700MC</td><td>Marco del bogie, viga portante</td><td>Alta relación resistencia/peso</td></tr><tr><td>S690QL</td><td>Enganche, rodamiento de eje</td><td>Resistencia a la fatiga</td></tr></tbody></table>',
    blog_demiryolu_kaynak_s6: '<h2>Criterios de Aceptación y Tasas END</h2><ul><li><strong>CP A + S3:</strong> EN ISO 5817 Nivel B</li><li><strong>CP B + S2:</strong> Nivel C</li><li><strong>CP C + S1:</strong> Nivel D</li></ul>',
    blog_demiryolu_kaynak_s7: '<h2>Coordinador Europeo (ECWS)</h2><p>Todo fabricante certificado debe emplear un <strong>Coordinador Europeo de Soldadura (ECWS)</strong> al nivel de IWE.</p><div class="callout"><p><strong>Realidad práctica:</strong> La certificación EN 15085 es un requisito imprescindible para acceder a proyectos ferroviarios. TCDD, Eurostar, DB y SNCF exigen CL1 o CL2 en sus licitaciones.</p></div>',
    blog_demiryolu_kaynak_cta_h3: 'Apoyo para su Proyecto de Soldadura Ferroviaria',
    blog_demiryolu_kaynak_cta_p: 'Contacte con nuestro equipo para certificación EN 15085 y procedimientos de soldadura ferroviaria.',
    blog_demiryolu_kaynak_cta_btn: 'Contactar →',

    blog_otomotiv_yan_title: 'Soluciones de Soldadura para Proveedores de Automoción: IATF 16949 & PPAP | ArmaWeld Blog',
    blog_otomotiv_yan_title_tag: 'Soluciones de Soldadura para Proveedores de Automoción: IATF 16949 & PPAP | ArmaWeld Blog',
    blog_otomotiv_yan_meta_desc: 'Fabricación soldada para proveedores de automoción, sistema de calidad IATF 16949, proceso PPAP, soldadura robótica, MAG y láser.',
    blog_otomotiv_yan_og_title: 'Soluciones de Soldadura para Proveedores de Automoción: IATF 16949 & PPAP',
    blog_otomotiv_yan_tag: 'Automoción y Fabricación',
    blog_otomotiv_yan_h1: 'Soluciones de Soldadura para Proveedores de Automoción: IATF 16949 & PPAP',
    blog_otomotiv_yan_read: '9 min de lectura',
    blog_otomotiv_yan_author: 'ArmaWeld Ingeniería',
    blog_otomotiv_yan_breadcrumb3: 'Proveedor de Automoción',
    blog_otomotiv_yan_s0: '<p>La fabricación soldada para proveedores de automoción opera bajo los estándares de calidad y velocidad más exigentes del mundo.</p>',
    blog_otomotiv_yan_s1: '<h2>Sistema de Calidad: IATF 16949</h2><ul><li>Gestión de calidad orientada a procesos (PFMEA, plan de control)</li><li>Control estadístico de procesos (SPC)</li><li>Análisis de sistema de medición (MSA)</li><li>Aprobación de primera pieza (PPAP)</li><li>Planificación avanzada de calidad (APQP)</li><li>Mejora continua (Kaizen, 5S, 8D)</li></ul>',
    blog_otomotiv_yan_s2: '<h2>Proceso PPAP</h2><p>PPAP — consta de 18 elementos:</p><ol><li>Registros de diseño</li><li>Documento de cambio de ingeniería</li><li>Aprobación de diseño del cliente</li><li>FMEA (DFMEA + PFMEA)</li><li>Diagrama de flujo del proceso</li><li>Plan de control</li><li>Estudios de análisis de sistema de medición</li><li>Resultados dimensionales</li><li>Resultados de ensayos de material y rendimiento</li><li>Informe de inspección de muestra inicial</li><li>Muestras de piezas</li><li>Muestra patrón</li><li>Equipos de medición</li><li>Registros aprobados por el cliente</li><li>Garantía/contrato</li><li>Verificación de lote</li><li>Informe de aprobación de apariencia (AAR)</li><li>Aprobación de envío de primera pieza (PSW)</li></ol>',
    blog_otomotiv_yan_s3: '<h2>Métodos de Soldadura en Automoción</h2><table class="data-table"><thead><tr><th>Método</th><th>Aplicación Típica</th><th>Eficiencia</th></tr></thead><tbody><tr><td>MAG Robótico (135)</td><td>Chasis, estructura inferior, bastidor de asiento</td><td>Muy alta</td></tr><tr><td>Soldadura por puntos (RSW)</td><td>Chapa fina, puertas, capó</td><td>Muy alta</td></tr><tr><td>Soldadura láser</td><td>Chapa fina, geometría compleja</td><td>Alta</td></tr><tr><td>MIG-Brazing (CuSi3)</td><td>Chapa galvanizada, cordón visible</td><td>Alta</td></tr><tr><td>TIG</td><td>Escape, inoxidable</td><td>Baja-media</td></tr></tbody></table>',
    blog_otomotiv_yan_s4: '<h2>Aceros para Automoción</h2><ul><li><strong>DC04 / DC05:</strong> Laminado en frío, embutición profunda — paneles de carrocería</li><li><strong>HX340LAD / HX420LAD:</strong> Alta resistencia, microaleado — chasis</li><li><strong>DP600 / DP800 / DP1000:</strong> Bifásico — componentes estructurales de seguridad</li><li><strong>USIBOR (1500MS):</strong> Conformado en caliente — parachoques, pilar B</li></ul>',
    blog_otomotiv_yan_s5: '<h2>Diseño de Célula de Soldadura Robótica</h2><ul><li><strong>Robot de 6 ejes:</strong> Fanuc, Yaskawa Motoman, Kuka, ABB</li><li><strong>Posicionador:</strong> 1–2 ejes, la pieza gira, el robot fijo</li><li><strong>Sistema de utillaje:</strong> Mordazas neumáticas, puntos de referencia automáticos</li><li><strong>Soldadura adaptativa:</strong> Escáner láser sigue el cordón</li></ul>',
    blog_otomotiv_yan_s6: '<h2>Ventajas de la Soldadura Láser</h2><ul><li>ZAC muy estrecha — distorsión mínima</li><li>Alta velocidad (5–10 m/min)</li><li>Bajo aporte térmico (0,1–0,5 kJ/mm)</li><li>Alta calidad visual en superficies vistas</li></ul>',
    blog_otomotiv_yan_s7: '<h2>Métodos de Control de Calidad</h2><ul><li><strong>SPC:</strong> Cpk ≥ 1,33 obligatorio</li><li><strong>Inspección visual automática:</strong> Cámara + escáner de línea láser</li><li><strong>Ensayo de aplastamiento:</strong> Resistencia al cizallamiento en puntos de soldadura</li><li><strong>Ensayo destructivo:</strong> Muestras periódicas de línea de producción</li></ul><div class="callout"><p><strong>Estándar de velocidad:</strong> La fabricación de proveedores de automoción trabaja con JIT y tiempo de ciclo. Tiempo de ciclo típico 60–90 segundos. La soldadura robótica es el único modo de alcanzar este ritmo.</p></div>',
    blog_otomotiv_yan_cta_h3: 'Apoyo para Proyectos de Soldadura en Automoción',
    blog_otomotiv_yan_cta_p: 'Fabricación soldada conforme a IATF 16949 y soporte en proceso PPAP.',
    blog_otomotiv_yan_cta_btn: 'Contactar →',

    blog_kaynak_isi_girdisi_title: 'Cálculo y Optimización del Aporte Térmico en Soldadura | ArmaWeld Blog',
    blog_kaynak_isi_girdisi_title_tag: 'Cálculo y Optimización del Aporte Térmico en Soldadura | ArmaWeld Blog',
    blog_kaynak_isi_girdisi_meta_desc: 'Qué es el aporte térmico, cómo calcularlo, fórmula EN ISO 1011, efecto en microestructura, relación con distorsión y propiedades mecánicas.',
    blog_kaynak_isi_girdisi_og_title: 'Cálculo y Optimización del Aporte Térmico en Soldadura',
    blog_kaynak_isi_girdisi_tag: 'Parámetros de Soldadura',
    blog_kaynak_isi_girdisi_h1: 'Cálculo y Optimización del Aporte Térmico en Soldadura',
    blog_kaynak_isi_girdisi_read: '8 min de lectura',
    blog_kaynak_isi_girdisi_author: 'ArmaWeld Ingeniería',
    blog_kaynak_isi_girdisi_breadcrumb3: 'Aporte Térmico',
    blog_kaynak_isi_girdisi_s0: '<p>El aporte térmico (Q o HI — Heat Input) es la energía transferida por unidad de longitud al cordón de soldadura, en <strong>kJ/mm</strong>. Determina directamente la microestructura, las propiedades mecánicas, la distorsión y el riesgo de defectos.</p><div class="callout"><p><strong>Regla general:</strong> Bajo aporte → microestructura dura y frágil, riesgo de fisuración. Alto aporte → ZAC blanda, distorsión. Mantenerse dentro del rango especificado en la WPS es obligatorio.</p></div>',
    blog_kaynak_isi_girdisi_s1: '<h2>Fórmula de Cálculo</h2><p><span class="tag-inline">Q = (k × U × I × 60) / (v × 1000)</span></p><ul><li><strong>Q:</strong> Aporte térmico (kJ/mm)</li><li><strong>U:</strong> Tensión (V)</li><li><strong>I:</strong> Intensidad (A)</li><li><strong>v:</strong> Velocidad de avance (mm/min)</li><li><strong>k:</strong> Factor de eficiencia térmica</li></ul>',
    blog_kaynak_isi_girdisi_s2: '<h2>Factores de Eficiencia Térmica (k)</h2><table class="data-table"><thead><tr><th>Proceso</th><th>ISO</th><th>k</th></tr></thead><tbody><tr><td>SAW (Arco Sumergido)</td><td>121</td><td>1,0</td></tr><tr><td>SMAW (Electrodo revestido)</td><td>111</td><td>0,8</td></tr><tr><td>MAG / MIG</td><td>135 / 131</td><td>0,8</td></tr><tr><td>TIG</td><td>141</td><td>0,6</td></tr><tr><td>Plasma</td><td>15</td><td>0,6</td></tr></tbody></table>',
    blog_kaynak_isi_girdisi_s3: '<h2>Ejemplo de Cálculo</h2><p>MAG soldando S355: U = 28 V, I = 280 A, v = 350 mm/min</p><p>Q = (0,8 × 28 × 280 × 60) / (350 × 1000) = <strong>1,075 kJ/mm</strong></p>',
    blog_kaynak_isi_girdisi_s4: '<h2>Rangos Recomendados por Acero</h2><table class="data-table"><thead><tr><th>Material</th><th>Q mín (kJ/mm)</th><th>Q máx (kJ/mm)</th></tr></thead><tbody><tr><td>S235JR</td><td>0,5</td><td>4,0</td></tr><tr><td>S355J2+N</td><td>0,5</td><td>3,5</td></tr><tr><td>S690QL</td><td>0,5</td><td>1,8</td></tr><tr><td>S960QL</td><td>0,5</td><td>1,5</td></tr></tbody></table>',
    blog_kaynak_isi_girdisi_s5: '<h2>Efectos del Bajo Aporte Térmico</h2><ul><li>Enfriamiento rápido → martensita (dura y frágil)</li><li>Dureza ZAC aumenta — puede superar 380 HV10</li><li>Mayor riesgo de fisuración en frío</li></ul>',
    blog_kaynak_isi_girdisi_s6: '<h2>Efectos del Alto Aporte Térmico</h2><ul><li>Crecimiento de grano en ZAC — tenacidad disminuye</li><li>Ablandamiento ZAC (aceros QT y TMCP)</li><li>Mayor distorsión y tensiones residuales</li></ul><h2>Estrategias de Gestión del Aporte Térmico</h2><h3>Para Reducir:</h3><ul><li>Reducir corriente o tensión; aumentar velocidad; usar modo pulsado</li></ul><h3>Para Aumentar:</h3><ul><li>Aumentar corriente; reducir velocidad; usar SAW o FCAW</li></ul>',
    blog_kaynak_isi_girdisi_s7: '<h2>Tiempo de Enfriamiento t8/5</h2><ul><li>t8/5 &lt; 5 s → Martensita, alta dureza</li><li>t8/5 = 10–20 s → Bainita, propiedades equilibradas</li><li>t8/5 > 30 s → Ferrita-perlita, baja resistencia, alta tenacidad</li></ul><div class="callout"><p><strong>Control práctico:</strong> Las modernas soldadoras digitales (Fronius TPS/i, Lincoln PowerWave, Lorch S-RoboMIG) muestran el aporte térmico en tiempo real.</p></div>',
    blog_kaynak_isi_girdisi_cta_h3: 'Apoyo en Optimización de Parámetros de Soldadura',
    blog_kaynak_isi_girdisi_cta_p: 'Soporte de ingeniería para elaboración de WPS y optimización del aporte térmico.',
    blog_kaynak_isi_girdisi_cta_btn: 'Contactar →',

    blog_pwht_title: 'Tratamiento Térmico Post-Soldadura (PWHT): Alivio de Tensiones | ArmaWeld Blog',
    blog_pwht_title_tag: 'Tratamiento Térmico Post-Soldadura (PWHT): Alivio de Tensiones | ArmaWeld Blog',
    blog_pwht_meta_desc: 'Qué es el PWHT, alivio de tensiones y revenido, requisitos EN 13445 y ASME VIII, guía de temperatura y duración.',
    blog_pwht_og_title: 'Tratamiento Térmico Post-Soldadura (PWHT): Alivio de Tensiones',
    blog_pwht_tag: 'Tratamiento Térmico y Calidad',
    blog_pwht_h1: 'Tratamiento Térmico Post-Soldadura (PWHT): Alivio de Tensiones',
    blog_pwht_read: '10 min de lectura',
    blog_pwht_author: 'ArmaWeld Ingeniería',
    blog_pwht_breadcrumb3: 'PWHT',
    blog_pwht_s0: '<p>El <strong>PWHT (Post Weld Heat Treatment — Tratamiento Térmico Post-Soldadura)</strong> consiste en calentar el componente soldado a una temperatura específica y enfriarlo de forma controlada. Objetivos: aliviar tensiones residuales de soldadura, estabilizar la microestructura y difundir el hidrógeno para eliminar el riesgo de fisuración en frío.</p>',
    blog_pwht_s1: '<h2>¿Por Qué Realizar PWHT?</h2><ul><li><strong>Alivio de tensiones:</strong> Las tensiones de tracción residuales pueden ser el 50–80% del límite elástico. El PWHT las reduce hasta un 80%.</li><li><strong>Difusión de hidrógeno:</strong> El hidrógeno difusible causante de fisuración diferida escapa durante el tratamiento.</li><li><strong>Mejora de tenacidad en ZAC:</strong> La ZAC endurecida se reviene; los valores Charpy mejoran.</li><li><strong>Estabilidad dimensional:</strong> Se evita la deformación en servicio.</li><li><strong>Resistencia a la corrosión:</strong> Se previene la sensibilización en aceros inoxidables.</li></ul>',
    blog_pwht_s2: '<h2>¿Cuándo es Obligatorio el PWHT?</h2><table class="data-table"><thead><tr><th>Norma</th><th>Requisito PWHT</th></tr></thead><tbody><tr><td>EN 13445 (recipiente a presión)</td><td>Acero al carbono t > 35 mm; baja aleación t > 19 mm</td></tr><tr><td>EN 13480 (tubería de proceso)</td><td>P-No 1: 19 mm; P-No 4–6: 13 mm</td></tr><tr><td>ASME VIII Div 1</td><td>Acero al carbono t > 38 mm</td></tr></tbody></table>',
    blog_pwht_s3: '<h2>Temperatura y Duración del PWHT</h2><table class="data-table"><thead><tr><th>Clase de Acero</th><th>Temperatura (°C)</th><th>Regla de Duración</th></tr></thead><tbody><tr><td>P-No 1 (S235, S355)</td><td>580–620</td><td>1 h / 25 mm, mín. 30 min</td></tr><tr><td>P-No 4 (2,25Cr-1Mo)</td><td>680–720</td><td>1 h / 25 mm</td></tr><tr><td>P-No 6 (12–13Cr martensítico)</td><td>720–780</td><td>Mínimo 2 h</td></tr><tr><td>P-No 8 (304L/316L)</td><td>1010–1100 (solubilización)</td><td>Por espesor</td></tr></tbody></table><div class="callout"><p><strong>S690QL y S960QL:</strong> El PWHT generalmente está <strong>PROHIBIDO</strong> para estos aceros QT. Superar la temperatura de revenido reduce irreversiblemente el límite elástico.</p></div>',
    blog_pwht_s4: '<h2>Velocidades de Calentamiento y Enfriamiento</h2><ul><li><strong>Velocidad de calentamiento (por encima de 300°C):</strong> Máx. 220°C/h × (25 / t)</li><li><strong>Tolerancia de temperatura de mantenimiento:</strong> ±20°C</li><li><strong>Velocidad de enfriamiento (por encima de 300°C):</strong> Máx. 275°C/h × (25 / t)</li><li><strong>Por debajo de 300°C:</strong> Enfriamiento libre al aire</li></ul>',
    blog_pwht_s5: '<h2>Métodos de Calentamiento</h2><ul><li><strong>Horno:</strong> El más uniforme, ideal para piezas pequeñas y medianas</li><li><strong>Inducción local:</strong> Habitual para soldaduras circunferenciales en tubería</li><li><strong>Manta resistiva:</strong> Económico para soldaduras locales</li><li><strong>Soplete de gas:</strong> Reparaciones en obra, difícil control de temperatura</li></ul>',
    blog_pwht_s6: '<h2>Colocación de Termopares</h2><ul><li>Mínimo 2 termopares (control entrada/salida)</li><li>Espesor > 50 mm: termopares separados en superficies interior y exterior</li><li>Todos los registros temperatura-tiempo conservados (10 años)</li></ul>',
    blog_pwht_s7: '<h2>Anchura de Banda de Calentamiento Local</h2><ul><li><strong>Banda calentada:</strong> 5 × R<sub>i</sub> × t</li><li><strong>Banda empapada:</strong> Mitad interior de la banda calentada</li><li><strong>Banda de control de gradiente:</strong> Zona aislada de 2,5 × R<sub>i</sub> × t más allá de la banda calentada</li></ul>',
    blog_pwht_s8: '<h2>Errores Frecuentes</h2><ul><li>Tiempo de mantenimiento insuficiente</li><li>Enfriamiento demasiado rápido</li><li>Termopares ausentes o mal ubicados</li><li>Anchura de banda insuficiente en calentamiento local</li><li>Aplicar PWHT a S690QL / S960QL (PROHIBIDO)</li></ul><h2>Verificación Post-PWHT</h2><ul><li>Ensayo de dureza (HV10): ¿dentro de los límites de la WPS?</li><li>END: PT/MT para nuevas grietas</li><li>Control dimensional: ¿distorsión ocurrida?</li></ul><div class="callout"><p><strong>Alcance ArmaWeld:</strong> PWHT en horno para piezas de hasta 8 m × 3 m × 3 m. Diagramas de proceso y registros de temperatura según EN 13445 y ASME VIII.</p></div>',
    blog_pwht_cta_h3: 'Servicios de PWHT y Alivio de Tensiones',
    blog_pwht_cta_p: 'Soporte de ingeniería para planificación y ejecución del tratamiento térmico post-soldadura.',
    blog_pwht_cta_btn: 'Contactar →'

  });


  // ==================== FRENCH ====================
  add('fr', {

    // --- WPQR ---
    blog_wpqr_title: 'WPQR - Certificat de Qualification de Procédure de Soudage | ArmaWeld Blog',
    blog_wpqr_title_tag: 'WPQR - Certificat de Qualification de Procédure de Soudage | ArmaWeld Blog',
    blog_wpqr_meta_desc: 'WPQR (Welding Procedure Qualification Record) - définition, portée, éléments essentiels, essais EN ISO 15614-1 et validité.',
    blog_wpqr_og_title: 'WPQR - Certificat de Qualification de Procédure de Soudage | ArmaWeld',
    blog_wpqr_tag: 'Qualification & Normes',
    blog_wpqr_h1: 'WPQR : Certificat de Qualification de Procédure de Soudage',
    blog_wpqr_read: '6 min de lecture',
    blog_wpqr_author: 'ArmaWeld Ingénierie',
    blog_wpqr_breadcrumb3: 'WPQR',
    blog_wpqr_s0: '<p>Le <strong>WPQR (Welding Procedure Qualification Record — Certificat de Qualification de Procédure de Soudage)</strong> est le document officiel qui prouve qu\'une procédure de soudage (WPS) a été qualifiée avec succès par des essais réalisés selon les normes EN ISO 15614-1, ASME IX ou AWS D1.1. Chaque assemblage de production est couvert par un WPQR valide.</p>',
    blog_wpqr_s1: '<h2>WPQR vs WPS : Différences Clés</h2><ul><li><strong>WPS (Welding Procedure Specification):</strong> La recette de soudage — indique comment souder.</li><li><strong>WPQR (Welding Procedure Qualification Record):</strong> La preuve que la recette a été testée et validée.</li><li>La WPS est dérivée du WPQR ; sans WPQR qualifié, la WPS n\'est pas valide en production.</li></ul>',
    blog_wpqr_s2: '<h2>Éléments Essentiels du WPQR</h2><table class="data-table"><thead><tr><th>Élément Essentiel</th><th>Limite de Variation</th></tr></thead><tbody><tr><td>Nuance de l\'acier de base</td><td>Groupe P-No / groupe ISO</td></tr><tr><td>Épaisseur de l\'assemblage test</td><td>0,5 – 2 × t</td></tr><tr><td>Procédé de soudage</td><td>GMAW, SMAW, SAW, TIG…</td></tr><tr><td>Métal d\'apport</td><td>Groupe AWS/EN + enrobage</td></tr><tr><td>Position</td><td>PA/PC/PF portée</td></tr><tr><td>Traitement thermique</td><td>Préchauffage / PWHT</td></tr></tbody></table>',
    blog_wpqr_s3: '<h2>Essais selon EN ISO 15614-1</h2><ul><li><strong>Contrôle visuel (VT):</strong> 100 %</li><li><strong>Radiographie (RT) ou Ultrasons (UT):</strong> 100 %</li><li><strong>Essai de pliage:</strong> 2 pliages face + 2 pliages envers</li><li><strong>Essai de traction:</strong> Résistance à la rupture ≥ métal de base</li><li><strong>Essai de résilience (Charpy):</strong> Si requis par la spécification du produit</li><li><strong>Dureté (HV10):</strong> ZAC et zone de liaison</li><li><strong>Examen macroscopique:</strong> Structure de la soudure</li></ul>',
    blog_wpqr_s4: '<h2>Validité et Renouvellement du WPQR</h2><ul><li>Un WPQR qualifié est valide en principe <strong>sans limite de temps</strong> tant que la production reste continue.</li><li>Un écart hors éléments essentiels invalide le WPQR → une nouvelle qualification est nécessaire.</li><li>L\'arrêt de production de plus de 6 mois peut exiger une vérification ou une re-qualification selon le référentiel client.</li><li>Les modifications de métal d\'apport, de groupe P-No ou de procédé constituent des éléments essentiels majeurs.</li></ul>',
    blog_wpqr_s5: '<h2>WPQR dans les Secteurs Réglementés</h2><ul><li><strong>Équipements sous pression (PED / EN 13445):</strong> WPQR obligatoire ; approuvé par un Organisme Notifié (ON).</li><li><strong>Construction métallique (EN 1090):</strong> Requis pour EXC2–EXC4.</li><li><strong>Ferroviaire (EN 15085):</strong> Qualifications CL1–CL4 selon le niveau de classe.</li><li><strong>Pétrole & gaz (API 1104 / ASME IX):</strong> WPQR spécifique au procédé.</li></ul>',
    blog_wpqr_cta_h3: 'Services de Qualification WPQR',
    blog_wpqr_cta_p: 'Nous gérons vos qualifications WPS/WPQR selon EN ISO 15614-1, ASME IX, EN 1090 et EN 15085.',
    blog_wpqr_cta_btn: 'Contactez-nous →',

    // --- Kaynak Hataları ---
    blog_kaynak_hatalari_title: 'Défauts de Soudage et Méthodes de Réparation | ArmaWeld Blog',
    blog_kaynak_hatalari_title_tag: 'Défauts de Soudage et Méthodes de Réparation | ArmaWeld Blog',
    blog_kaynak_hatalari_meta_desc: 'Défauts de soudage fissures, porosités, défauts de fusion selon EN ISO 6520, méthodes END, procédures de réparation soudage.',
    blog_kaynak_hatalari_og_title: 'Défauts de Soudage et Méthodes de Réparation | ArmaWeld',
    blog_kaynak_hatalari_tag: 'Qualité & Contrôle',
    blog_kaynak_hatalari_h1: 'Défauts de Soudage et Méthodes de Réparation',
    blog_kaynak_hatalari_read: '8 min de lecture',
    blog_kaynak_hatalari_author: 'ArmaWeld Ingénierie',
    blog_kaynak_hatalari_breadcrumb3: 'Défauts de Soudage',
    blog_kaynak_hatalari_s0: '<p>Les <strong>défauts de soudage</strong> sont des discontinuités ou irrégularités géométriques se produisant dans l\'assemblage soudé. Selon EN ISO 6520-1, ils sont classés en 6 groupes principaux : fissures, cavités (porosités), inclusions solides, manques de fusion, imperfections de forme et défauts divers. Chaque défaut affecte différemment la résistance mécanique et la durée de vie en fatigue.</p>',
    blog_kaynak_hatalari_s1: '<h2>Fissures (Groupe 1)</h2><p>Les fissures sont les défauts les plus dangereux car elles se propagent sous charge cyclique. On distingue :</p><ul><li><strong>Fissures à froid (hydrogène) :</strong> se manifestent dans les 48 h après soudage. Causes : hydrogène diffusible, contrainte résiduelle, microstructure sensible (martensitique). Prévention : préchauffage, métal d\'apport à faible hydrogène.</li><li><strong>Fissures à chaud :</strong> se produisent pendant la solidification. Liées aux impuretés (S, P). Contrôle par le ratio Mn/S.</li><li><strong>Fissures de réchauffage :</strong> surviennent lors du PWHT dans la ZAC des aciers alliés (Cr-Mo-V).</li></ul>',
    blog_kaynak_hatalari_s2: '<h2>Porosités (Groupe 2)</h2><p>Les porosités sont des cavités gazeuses emprisonnées dans le métal fondu. Classification :</p><ul><li><strong>Porosités sphériques :</strong> isolées ou en groupe (EN ISO 6520-1 : type 2011/2012)</li><li><strong>Soufflures allongées (vermiculaires) :</strong> résultent du dégagement de CO ou N₂</li><li><strong>Porosités de retrait (retassures) :</strong> criques inter-dendritiques lors de la solidification</li></ul><p>Causes principales : humidité dans le flux ou l\'enrobage, contamination par l\'huile, débit de gaz inadapté, métal de base sale.</p>',
    blog_kaynak_hatalari_s3: '<h2>Défauts de Fusion et de Pénétration (Groupe 4)</h2><ul><li><strong>Manque de fusion latéral :</strong> absence de fusion entre cordon et métal de base → énergie d\'arc insuffisante ou angle de pistolet incorrect.</li><li><strong>Manque de fusion entre passes :</strong> nettoyage inter-passes insuffisant, passes trop larges.</li><li><strong>Manque de pénétration :</strong> défaut de remplissage à la racine ; critique pour les soudures en X ou V.</li></ul>',
    blog_kaynak_hatalari_s4: '<h2>Imperfections de Forme (Groupe 5)</h2><table class="data-table"><thead><tr><th>Type</th><th>Cause</th><th>Limite EN 5817</th></tr></thead><tbody><tr><td>Caniveau (undercut)</td><td>Vitesse trop élevée, angle incorrect</td><td>≤ 0,5 mm (classe B)</td></tr><tr><td>Surépaisseur excessive</td><td>Vitesse trop faible</td><td>≤ 1 mm + 0,1b</td></tr><tr><td>Décalage (hi-lo)</td><td>Mauvais assemblage</td><td>≤ 0,5 mm (classe B)</td></tr><tr><td>Effondrement de la racine</td><td>Ouverture de racine trop large</td><td>≤ 1 mm</td></tr></tbody></table>',
    blog_kaynak_hatalari_s5: '<h2>Méthodes de Contrôle Non Destructif (END)</h2><ul><li><strong>VT (Contrôle Visuel) :</strong> première étape obligatoire selon EN ISO 17637.</li><li><strong>PT (Ressuage) :</strong> fissures et pores débouchants en surface.</li><li><strong>MT (Magnétoscopie) :</strong> matériaux ferromagnétiques ; sensible aux défauts sub-surfaciques.</li><li><strong>UT (Ultrasons) :</strong> défauts internes volumétriques, mesure d\'épaisseur.</li><li><strong>RT (Radiographie) :</strong> porosités et inclusions ; archives permanentes.</li><li><strong>TOFD / Phased Array :</strong> méthodes avancées pour équipements sous pression.</li></ul>',
    blog_kaynak_hatalari_s6: '<h2>Procédure de Réparation par Soudage</h2><ol><li>Localisation du défaut par END.</li><li>Marquage et excavation par meulage ou gougeage à l\'arc-air.</li><li>Contrôle END de l\'excavation (MT ou PT).</li><li>Préchauffage si requis (même conditions que la WPS originale).</li><li>Soudage de réparation selon une WRS (Welding Repair Specification) approuvée.</li><li>PWHT si le matériau et l\'épaisseur l\'exigent.</li><li>Contrôle END final de la zone réparée.</li></ol><div class="callout"><p><strong>Important :</strong> Selon EN 13445 et ASME VIII, les réparations sur équipements sous pression nécessitent l\'approbation de l\'Organisme Notifié et une documentation complète.</p></div>',
    blog_kaynak_hatalari_cta_h3: 'Services de Contrôle Qualité Soudage',
    blog_kaynak_hatalari_cta_p: 'Inspection END, analyse de défauts et gestion des réparations par soudage selon EN ISO 17635.',
    blog_kaynak_hatalari_cta_btn: 'Contactez-nous →',

    // --- Ön Isıtma ---
    blog_on_isitma_title: 'Préchauffage en Soudage : Calcul selon EN ISO 13916 | ArmaWeld Blog',
    blog_on_isitma_title_tag: 'Préchauffage en Soudage : Calcul selon EN ISO 13916 | ArmaWeld Blog',
    blog_on_isitma_meta_desc: 'Préchauffage en soudage, calcul de température minimale, méthode carbone équivalent CE, EN ISO 13916, prévention fissuration à froid.',
    blog_on_isitma_og_title: 'Préchauffage en Soudage : Calcul selon EN ISO 13916 | ArmaWeld',
    blog_on_isitma_tag: 'Procédés de Soudage',
    blog_on_isitma_h1: 'Préchauffage en Soudage : Calcul et Application',
    blog_on_isitma_read: '7 min de lecture',
    blog_on_isitma_author: 'ArmaWeld Ingénierie',
    blog_on_isitma_breadcrumb3: 'Préchauffage',
    blog_on_isitma_s0: '<p>Le <strong>préchauffage</strong> consiste à porter le métal de base à une température minimale avant soudage. Objectifs principaux : ralentir la vitesse de refroidissement, réduire la teneur en hydrogène dans la ZAC, abaisser les contraintes de retrait et prévenir la fissuration à froid (fissuration sous cordon). Requis principalement pour les aciers à fort carbone équivalent et les grandes épaisseurs.</p>',
    blog_on_isitma_s1: '<h2>Température de Préchauffage Minimale</h2><p>La méthode la plus utilisée est celle du <strong>carbone équivalent (CE)</strong> selon EN ISO 13916 / CEN TR 13187 :</p><ul><li><strong>CE (IIW) = C + Mn/6 + (Cr+Mo+V)/5 + (Ni+Cu)/15</strong></li><li>CE ≤ 0,40 : préchauffage généralement non nécessaire (t ≤ 20 mm)</li><li>0,40 < CE ≤ 0,45 : Tp ≥ 75 °C</li><li>0,45 < CE ≤ 0,60 : Tp ≥ 150 °C</li><li>CE > 0,60 : Tp ≥ 200 °C (ou méthode détaillée EN ISO 13916)</li></ul>',
    blog_on_isitma_s2: '<h2>Facteurs Influençant la Température de Préchauffage</h2><ul><li><strong>Carbone équivalent (CE) :</strong> Plus CE est élevé, plus le risque de trempe martensitique est grand.</li><li><strong>Épaisseur du joint :</strong> Les grandes épaisseurs augmentent la vitesse de refroidissement (facteur de masse).</li><li><strong>Hydrogène diffusible (HD) :</strong> HD > 15 ml/100g → préchauffage obligatoire. Électrodes basiques : HD < 5 ml/100g.</li><li><strong>Niveau de contrainte :</strong> Rigidité élevée de la structure → augmentation de la température de préchauffage.</li></ul>',
    blog_on_isitma_s3: '<h2>Méthodes d\'Application du Préchauffage</h2><ul><li><strong>Chauffage aux brûleurs gaz :</strong> Le plus économique ; uniforme pour les grandes surfaces.</li><li><strong>Couvertures résistives :</strong> Régulation électronique de la température, idéales pour les viroles.</li><li><strong>Induction :</strong> Chauffage rapide et uniforme ; investissement initial plus élevé.</li><li><strong>Four :</strong> Petites pièces ; homogénéité parfaite.</li></ul>',
    blog_on_isitma_s4: '<h2>Mesure et Contrôle de la Température</h2><ul><li><strong>Thermomètre à contact (thermocouple) :</strong> mesure la plus fiable selon EN ISO 13916.</li><li><strong>Pyrométrie infrarouge :</strong> mesure sans contact ; sensible à l\'émissivité (facteur ε).</li><li><strong>Crayon thermique (Templestik) :</strong> contrôle rapide en production ; pour températures fixes.</li><li>La mesure doit être réalisée <strong>à au moins 75 mm du bord du joint</strong>.</li></ul>',
    blog_on_isitma_s5: '<h2>Température Interpasse</h2><p>La température interpasse est la température du métal de base mesurée avant le dépôt de chaque passe. Valeurs typiques :</p><ul><li><strong>Aciers au carbone :</strong> 250 °C max.</li><li><strong>Aciers inoxydables austénitiques :</strong> 150 °C max. (pour limiter la sensibilisation).</li><li><strong>Aciers Cr-Mo :</strong> 300 °C max.</li><li>Une température interpasse excessive peut dégrader la résilience de la ZAC.</li></ul>',
    blog_on_isitma_s6: '<h2>Températures de Préchauffage par Nuance</h2><table class="data-table"><thead><tr><th>Nuance</th><th>CE</th><th>Préchauffage (t = 25 mm)</th></tr></thead><tbody><tr><td>S235 / S275</td><td>0,35–0,38</td><td>Non requis</td></tr><tr><td>S355</td><td>0,39–0,43</td><td>75 °C</td></tr><tr><td>S460</td><td>0,44–0,53</td><td>100–150 °C</td></tr><tr><td>S690QL</td><td>0,54–0,62</td><td>150–200 °C</td></tr><tr><td>13CrMo4-5</td><td>0,60–0,70</td><td>200–250 °C</td></tr></tbody></table>',
    blog_on_isitma_cta_h3: 'Support Technique Préchauffage',
    blog_on_isitma_cta_p: 'Calculs de préchauffage, développement WPS et qualification selon EN ISO 15614-1.',
    blog_on_isitma_cta_btn: 'Contactez-nous →',

    // --- Distorsiyon ---
    blog_kaynak_distors_title: 'Distorsion de Soudage : Causes et Méthodes de Contrôle | ArmaWeld Blog',
    blog_kaynak_distors_title_tag: 'Distorsion de Soudage : Causes et Méthodes de Contrôle | ArmaWeld Blog',
    blog_kaynak_distors_meta_desc: 'Distorsion de soudage angulaire longitudinale transversale, méthodes de contrôle par bridage et séquence de soudage, redressage thermique.',
    blog_kaynak_distors_og_title: 'Distorsion de Soudage : Causes et Méthodes de Contrôle | ArmaWeld',
    blog_kaynak_distors_tag: 'Qualité & Fabrication',
    blog_kaynak_distors_h1: 'Distorsion de Soudage : Causes et Méthodes de Contrôle',
    blog_kaynak_distors_read: '7 min de lecture',
    blog_kaynak_distors_author: 'ArmaWeld Ingénierie',
    blog_kaynak_distors_breadcrumb3: 'Distorsion',
    blog_kaynak_distors_s0: '<p>La <strong>distorsion de soudage</strong> désigne la déformation permanente de la pièce résultant des contraintes thermiques générées pendant le soudage. Elle se manifeste sous plusieurs formes — retrait longitudinal, retrait transversal, déformation angulaire, gauchissement — et peut rendre un assemblage hors tolérances géométriques. La compréhension et le contrôle de la distorsion sont essentiels pour la qualité de fabrication.</p>',
    blog_kaynak_distors_s1: '<h2>Types de Distorsion</h2><ul><li><strong>Retrait longitudinal :</strong> Raccourcissement dans l\'axe du cordon — typiquement 0,1–0,3 % de la longueur.</li><li><strong>Retrait transversal :</strong> Réduction de la largeur du joint — dépend de la préparation et du volume de métal déposé.</li><li><strong>Déformation angulaire :</strong> Rotation autour de l\'axe du cordon ; critique dans les joints en V.</li><li><strong>Gauchissement :</strong> Flambement des tôles minces sous l\'effet des contraintes compressives.</li><li><strong>Déflexion (cambre) :</strong> Fléchissement des poutres soudées sous les forces longitudinales.</li></ul>',
    blog_kaynak_distors_s2: '<h2>Facteurs Influençant la Distorsion</h2><ul><li><strong>Énergie de soudage :</strong> Volume de métal déposé et apport thermique plus élevés → plus grande distorsion.</li><li><strong>Préparation du joint :</strong> Les joints en V simples sont plus sujets à la déformation angulaire que les joints en X ou double V.</li><li><strong>Séquence de soudage :</strong> Le sens et l\'ordre des passes modifient la distribution des contraintes.</li><li><strong>Rigidité de la structure :</strong> Les structures bridées tolèrent moins de déformation mais accumulent plus de contraintes internes.</li><li><strong>Propriétés du matériau :</strong> L\'acier inoxydable austénitique se déforme environ 2–3 fois plus que l\'acier au carbone (coefficient de dilatation plus élevé).</li></ul>',
    blog_kaynak_distors_s3: '<h2>Méthodes de Prévention</h2><ul><li><strong>Bridage et gabarits :</strong> Immobiliser la pièce pendant le soudage réduit la distorsion angulaire.</li><li><strong>Prédéformation (cambrage) :</strong> Donner à la pièce une déformation opposée anticipée avant soudage.</li><li><strong>Optimisation de la séquence :</strong> Alternance des passes des deux côtés (soudure en X) ; progression en retour (back-step).</li><li><strong>Réduction de l\'énergie de soudage :</strong> Passes multiples de faible énergie plutôt qu\'une seule passe de forte énergie.</li><li><strong>Symétrie de la soudure :</strong> Préférer les joints symétriques (double V, double J) pour équilibrer les déformations.</li></ul>',
    blog_kaynak_distors_s4: '<h2>Méthodes de Redressage</h2><ul><li><strong>Redressage mécanique :</strong> Pressage ou martelage ; adapté aux aciers au carbone (attention à la fragilisation).</li><li><strong>Redressage thermique à la flamme :</strong> Chauffage localisé puis refroidissement contrôlé → contraction thermique ciblée. Températures typiques : 600–700 °C pour aciers au carbone.</li><li><strong>Recuit de détensionnement :</strong> PWHT pour relâcher les contraintes résiduelles sans correction géométrique active.</li></ul><div class="callout"><p><strong>Note :</strong> Le redressage thermique est interdit sur les aciers THLE (S690QL, S960QL) au-dessus de la température de revenu spécifiée par le fabricant. Consulter la fiche technique du métal de base avant toute intervention.</p></div>',
    blog_kaynak_distors_cta_h3: 'Contrôle de la Distorsion et Conseil Technique',
    blog_kaynak_distors_cta_p: 'Optimisation de la séquence de soudage et solutions de bridage pour un assemblage conforme aux tolérances.',
    blog_kaynak_distors_cta_btn: 'Contactez-nous →',

    // --- Kaynak Pozisyonları ---
    blog_kaynak_pozis_title: 'Positions de Soudage : PA PB PC PF et Qualifications | ArmaWeld Blog',
    blog_kaynak_pozis_title_tag: 'Positions de Soudage : PA PB PC PF et Qualifications | ArmaWeld Blog',
    blog_kaynak_pozis_meta_desc: 'Positions de soudage PA PB PC PD PE PF PG selon EN ISO 6947, qualification soudeur, soudage en position difficile.',
    blog_kaynak_pozis_og_title: 'Positions de Soudage : PA PB PC PF et Qualifications | ArmaWeld',
    blog_kaynak_pozis_tag: 'Procédés de Soudage',
    blog_kaynak_pozis_h1: 'Positions de Soudage : Codes, Influences et Qualifications',
    blog_kaynak_pozis_read: '6 min de lecture',
    blog_kaynak_pozis_author: 'ArmaWeld Ingénierie',
    blog_kaynak_pozis_breadcrumb3: 'Positions de Soudage',
    blog_kaynak_pozis_s0: '<p>La <strong>position de soudage</strong> définit l\'orientation spatiale du joint pendant l\'exécution de la soudure. Elle influence directement la fluidité du bain fondu, la qualité du profil du cordon et les paramètres de procédé. Les codes EN ISO 6947 (PA, PB, PC, PD, PE, PF, PG) sont universellement utilisés en Europe dans les WPS et qualifications soudeur.</p>',
    blog_kaynak_pozis_s1: '<h2>Codes de Position EN ISO 6947</h2><table class="data-table"><thead><tr><th>Code</th><th>Définition</th><th>Équivalent AWS</th></tr></thead><tbody><tr><td>PA</td><td>À plat (plat sur table)</td><td>1G / 1F</td></tr><tr><td>PB</td><td>En angle à plat (cornière horizontale)</td><td>2F</td></tr><tr><td>PC</td><td>En position horizontale</td><td>2G</td></tr><tr><td>PD</td><td>En angle déjeté (cornière en dessous)</td><td>4F</td></tr><tr><td>PE</td><td>En plafond</td><td>4G</td></tr><tr><td>PF</td><td>En montant (vertical ascendant)</td><td>3G up</td></tr><tr><td>PG</td><td>En descendant (vertical descendant)</td><td>3G down</td></tr></tbody></table>',
    blog_kaynak_pozis_s2: '<h2>Influence de la Position sur la Qualité</h2><ul><li><strong>PA (à plat) :</strong> Conditions les plus favorables ; bain soutenu par gravité ; productivité maximale.</li><li><strong>PC (horizontal) :</strong> Tendance à la coulure et à la formation de caniveaux ; largeur de passe limitée.</li><li><strong>PF (montant) :</strong> Bain visqueux requis ; paramètres réduits ; risque de collage si l\'énergie est trop élevée.</li><li><strong>PE (plafond) :</strong> Bain liquide suspendu par tension superficielle ; passes étroites obligatoires ; risque maximal de projection.</li><li><strong>PG (descendant) :</strong> Possible uniquement pour certains procédés (FCAW, SMAW avec électrodes cellulosiques) ; productivité élevée mais sensibilité aux défauts.</li></ul>',
    blog_kaynak_pozis_s3: '<h2>Portée des Qualifications Soudeur par Position</h2><p>Selon EN ISO 9606-1, une qualification en position difficile confère une portée élargie :</p><ul><li><strong>PA</strong> qualifie uniquement PA.</li><li><strong>PC</strong> qualifie PA + PC.</li><li><strong>PF</strong> qualifie PA + PB + PC + PF.</li><li><strong>PE</strong> qualifie toutes les positions sauf PG.</li><li><strong>PG</strong> qualifie uniquement PG.</li></ul>',
    blog_kaynak_pozis_s4: '<h2>Positions des Tubes (Pipes)</h2><ul><li><strong>PA (tube tournant, axe horizontal) :</strong> Tube rotatif — position la plus favorable.</li><li><strong>PC (tube tournant, axe vertical) :</strong> Soudage horizontal continu.</li><li><strong>PH (tube fixe, axe horizontal — soudage montant) :</strong> Qualifie 5G up.</li><li><strong>PJ (tube fixe, axe horizontal — soudage descendant) :</strong> Qualifie 5G down.</li><li><strong>H-L045 (tube fixe incliné à 45°) :</strong> La position la plus difficile ; qualifie toutes les positions de tube.</li></ul>',
    blog_kaynak_pozis_s5: '<h2>Recommandations pour le Soudage en Position Difficile</h2><ul><li>Réduire l\'énergie de soudage (tension et ampérage) en PE et PF.</li><li>Utiliser un métal d\'apport avec une viscosité accrue du bain (ex. : flux basse pénétration pour FCAW).</li><li>Réaliser des passes étroites et régulières plutôt que des passes larges en oscillation.</li><li>Contrôler l\'angle de travail et de progression pour maîtriser la gravité du bain.</li><li>En MIG/MAG, augmenter la vitesse d\'avance et réduire le courant en PF pour limiter l\'apport thermique.</li></ul>',
    blog_kaynak_pozis_cta_h3: 'Qualification de Soudeurs et Développement WPS',
    blog_kaynak_pozis_cta_p: 'Programmes de qualification soudeur pour toutes positions selon EN ISO 9606-1 et ASME IX.',
    blog_kaynak_pozis_cta_btn: 'Contactez-nous →',

    // --- Kaynak Sembolizasyonu ---
    blog_kaynak_sembol_title: 'Symbolisation de Soudage : Lecture des Plans selon EN ISO 2553 | ArmaWeld Blog',
    blog_kaynak_sembol_title_tag: 'Symbolisation de Soudage : Lecture des Plans selon EN ISO 2553 | ArmaWeld Blog',
    blog_kaynak_sembol_meta_desc: 'Symboles de soudage EN ISO 2553 AWS A2.4, ligne de référence, symboles de base, complémentaires et lecture de plans de fabrication soudée.',
    blog_kaynak_sembol_og_title: 'Symbolisation de Soudage : Lecture des Plans selon EN ISO 2553 | ArmaWeld',
    blog_kaynak_sembol_tag: 'Normes & Documentation',
    blog_kaynak_sembol_h1: 'Symbolisation de Soudage : Lire les Plans de Fabrication',
    blog_kaynak_sembol_read: '8 min de lecture',
    blog_kaynak_sembol_author: 'ArmaWeld Ingénierie',
    blog_kaynak_sembol_breadcrumb3: 'Symboles de Soudage',
    blog_kaynak_sembol_s0: '<p>La <strong>symbolisation de soudage</strong> est la langue graphique universelle qui permet aux concepteurs de communiquer avec précision les exigences de soudage aux fabricants. La norme EN ISO 2553 (Europe) et AWS A2.4 (Amérique du Nord) définissent cette symbolisation. Une mauvaise lecture des symboles peut entraîner des non-conformités coûteuses ou des risques de sécurité.</p>',
    blog_kaynak_sembol_s1: '<h2>Éléments de la Ligne de Référence</h2><ul><li><strong>Ligne de référence :</strong> Ligne horizontale à laquelle tous les symboles sont rattachés.</li><li><strong>Flèche :</strong> Indique le joint à souder ; peut être coudée pour désigner le côté raccord.</li><li><strong>Symbole élémentaire :</strong> Représente le type de soudure (V, X, I, angle…).</li><li><strong>Cote du symbole :</strong> Dimension (gorge, longueur, espacement).</li><li><strong>Symboles complémentaires :</strong> Finition de surface, soudure tout autour, soudure en chantier…</li><li><strong>Queue :</strong> Références au procédé, à la classe END ou à la WPS.</li></ul>',
    blog_kaynak_sembol_s2: '<h2>Symboles Élémentaires Courants</h2><table class="data-table"><thead><tr><th>Symbole</th><th>Type de Soudure</th><th>Application Typique</th></tr></thead><tbody><tr><td>—</td><td>Soudure en I (bout à bout sans chanfrein)</td><td>Tôles minces</td></tr><tr><td>V</td><td>Soudure en V</td><td>Tôles t = 6–25 mm</td></tr><tr><td>X</td><td>Soudure en double V</td><td>Tôles t > 20 mm</td></tr><tr><td>△</td><td>Soudure d\'angle (filet)</td><td>Joints en T, cornières</td></tr><tr><td>J</td><td>Soudure en J</td><td>Accès limité, grande épaisseur</td></tr><tr><td>U</td><td>Soudure en U</td><td>Tuyauteries haute pression</td></tr></tbody></table>',
    blog_kaynak_sembol_s3: '<h2>Position des Symboles par Rapport à la Ligne de Référence</h2><ul><li><strong>Symbole en dessous de la ligne :</strong> Soudure du côté flèche (côté visible).</li><li><strong>Symbole au-dessus de la ligne :</strong> Soudure du côté opposé à la flèche.</li><li><strong>Symboles des deux côtés :</strong> Soudure des deux côtés (double V, double angle).</li><li><strong>Cercle à l\'origine de la flèche :</strong> Soudure tout autour (soudure fermée).</li><li><strong>Drapeau à l\'origine :</strong> Soudure en chantier (sur site).</li></ul>',
    blog_kaynak_sembol_s4: '<h2>Cotation des Soudures d\'Angle</h2><ul><li><strong>a (gorge théorique) :</strong> Hauteur du triangle inscrit dans la section de soudure — dimension de résistance.</li><li><strong>z (côté du carré) :</strong> Côté du triangle isocèle — z = a × √2.</li><li><strong>l (longueur) :</strong> Longueur effective du cordon.</li><li><strong>e (espacement) :</strong> Distance entre cordons discontinus.</li><li><strong>n (nombre) :</strong> Nombre de segments pour les cordons discontinus.</li></ul>',
    blog_kaynak_sembol_s5: '<h2>Symboles de Finition et d\'Inspection</h2><ul><li><strong>C :</strong> Finition par meulage (concave)</li><li><strong>M :</strong> Finition par meulage (affleurant)</li><li><strong>G :</strong> Finition par meulage</li><li><strong>Classe END :</strong> Notée en queue (ex. : VT2, RT2 selon EN ISO 17635)</li><li><strong>Niveau de qualité :</strong> Classe B/C/D selon EN ISO 5817 notée en queue</li></ul>',
    blog_kaynak_sembol_s6: '<h2>Différences EN ISO 2553 / AWS A2.4</h2><table class="data-table"><thead><tr><th>Critère</th><th>EN ISO 2553</th><th>AWS A2.4</th></tr></thead><tbody><tr><td>Côté flèche</td><td>Symbole sous la ligne</td><td>Symbole sous la ligne</td></tr><tr><td>Côté opposé</td><td>Symbole au-dessus de la ligne</td><td>Symbole au-dessus de la ligne</td></tr><tr><td>Gorge (a)</td><td>a = gorge théorique</td><td>Dimension de jambe (leg size)</td></tr><tr><td>Soudure tout autour</td><td>Cercle à l\'intersection</td><td>Cercle à l\'intersection</td></tr><tr><td>Soudure en chantier</td><td>Drapeau rempli</td><td>Drapeau vide</td></tr></tbody></table>',
    blog_kaynak_sembol_s7: '<h2>Erreurs de Lecture Fréquentes</h2><ul><li>Confondre côté flèche et côté opposé → cordon du mauvais côté.</li><li>Interpréter la cote <em>z</em> comme <em>a</em> → sous-dimensionnement de 30 % de la résistance.</li><li>Omettre les symboles de finition → profil de surface non conforme à EN 5817.</li><li>Ignorer le drapeau de chantier → soudure réalisée en atelier au lieu d\'être réalisée sur site.</li><li>Confondre les normes EN et AWS sur un même plan → erreurs d\'interprétation systématiques.</li></ul>',
    blog_kaynak_sembol_cta_h3: 'Formation et Documentation Technique',
    blog_kaynak_sembol_cta_p: 'Élaboration de plans de soudage et de WPS conformes aux normes EN ISO 2553 et AWS A2.4.',
    blog_kaynak_sembol_cta_btn: 'Contactez-nous →',

    // --- Basınçlı Kap ---
    blog_basincli_kap_title: 'Fabrication d\'Équipements sous Pression : PED 2014/68/EU et EN 13445 | ArmaWeld Blog',
    blog_basincli_kap_title_tag: 'Fabrication d\'Équipements sous Pression : PED 2014/68/EU et EN 13445 | ArmaWeld Blog',
    blog_basincli_kap_meta_desc: 'Fabrication équipements sous pression, directive PED 2014/68/EU, EN 13445, classification catégories, évaluation de conformité, marquage CE.',
    blog_basincli_kap_og_title: 'Fabrication d\'Équipements sous Pression : PED 2014/68/EU et EN 13445 | ArmaWeld',
    blog_basincli_kap_tag: 'Équipements Industriels',
    blog_basincli_kap_h1: 'Fabrication d\'Équipements sous Pression : Guide PED et EN 13445',
    blog_basincli_kap_read: '9 min de lecture',
    blog_basincli_kap_author: 'ArmaWeld Ingénierie',
    blog_basincli_kap_breadcrumb3: 'Équipements sous Pression',
    blog_basincli_kap_s0: '<p>La <strong>fabrication d\'équipements sous pression</strong> est réglementée en Europe par la <strong>Directive Équipements sous Pression (PED) 2014/68/EU</strong>. Tout équipement sous pression (réservoirs, échangeurs, tuyauteries) mis sur le marché européen doit satisfaire aux exigences essentielles de sécurité (ESR) de cette directive. La norme harmonisée <strong>EN 13445</strong> est la référence technique de conformité.</p>',
    blog_basincli_kap_s1: '<h2>Classification des Équipements (Catégories PED)</h2><p>La PED classe les équipements en 4 catégories (I à IV) en fonction du produit PS × V (pression × volume) ou PS × DN :</p><ul><li><strong>Catégorie I :</strong> Risque faible — auto-certification (module A).</li><li><strong>Catégorie II :</strong> Risque modéré — intervention d\'un Organisme Notifié (ON) requise.</li><li><strong>Catégorie III :</strong> Risque élevé — approbation du système qualité ou examen de type.</li><li><strong>Catégorie IV :</strong> Risque très élevé — examen CE de type + approbation système qualité.</li></ul>',
    blog_basincli_kap_s2: '<h2>EN 13445 — Structure et Parties</h2><table class="data-table"><thead><tr><th>Partie</th><th>Contenu</th></tr></thead><tbody><tr><td>EN 13445-1</td><td>Généralités</td></tr><tr><td>EN 13445-2</td><td>Matériaux</td></tr><tr><td>EN 13445-3</td><td>Conception</td></tr><tr><td>EN 13445-4</td><td>Fabrication</td></tr><tr><td>EN 13445-5</td><td>Inspection et contrôle</td></tr><tr><td>EN 13445-6</td><td>Fonte sphéroïdale</td></tr><tr><td>EN 13445-8</td><td>Équipements en aluminium</td></tr></tbody></table>',
    blog_basincli_kap_s3: '<h2>Exigences de Soudage selon EN 13445-4</h2><ul><li><strong>Coordination du soudage :</strong> Responsable de la coordination du soudage (EN ISO 14731) obligatoire.</li><li><strong>Qualification des procédures :</strong> WPS + WPQR selon EN ISO 15614-1 ; approbation de l\'ON requise pour cat. III–IV.</li><li><strong>Qualification des soudeurs :</strong> EN ISO 9606-1 ; tenue à jour obligatoire.</li><li><strong>Joints de catégorie A (longitudinaux) :</strong> Contrôle RT/UT 100 % pour cat. III–IV.</li><li><strong>Joints de catégorie B (circonférentiels) :</strong> Contrôle selon le groupe d\'application de l\'équipement.</li></ul>',
    blog_basincli_kap_s4: '<h2>PWHT (Traitement Thermique Post-Soudage) selon EN 13445</h2><ul><li>Aciers au carbone : PWHT obligatoire si t > 35 mm.</li><li>Aciers faiblement alliés : PWHT si t > 19 mm.</li><li>Aciers Cr-Mo : PWHT systématique indépendamment de l\'épaisseur.</li><li>La température et la durée du traitement doivent être documentées et enregistrées.</li></ul>',
    blog_basincli_kap_s5: '<h2>Essai Hydraulique</h2><ul><li>Pression d\'essai : Ph = 1,25 × PS × (f_t / f_d) — généralement 1,25–1,43 × PS.</li><li>Durée de maintien : minimum 30 minutes.</li><li>Inspecter toutes les soudures sous pression d\'essai.</li><li>Alternative : essai pneumatique avec accord de l\'ON (risque accru — justification requise).</li></ul>',
    blog_basincli_kap_s6: '<h2>Marquage CE et Déclaration de Conformité</h2><ul><li>Le marquage CE doit figurer sur chaque équipement avec le numéro d\'identification de l\'ON.</li><li>La Déclaration de Conformité (DoC) doit être fournie avec l\'équipement.</li><li>Le Dossier Technique de Fabrication (DTF) doit être conservé 10 ans minimum.</li><li>Le carnet de données (Datenblatt) contient toutes les spécifications techniques et les résultats des contrôles.</li></ul>',
    blog_basincli_kap_s7: '<h2>Points d\'Attention Fréquents</h2><ul><li>Sélection incorrecte de la catégorie PED → sous ou sur-évaluation des exigences.</li><li>Traçabilité des matériaux insuffisante (certificats EN 10204 3.1 requis pour cat. III–IV).</li><li>WPS non qualifiée par l\'ON → rejet à la réception.</li><li>Absence de documentation PWHT → non-conformité systématique.</li><li>Oubli de la plaque signalétique réglementaire (PS, TS, volume, marquage CE).</li></ul>',
    blog_basincli_kap_cta_h3: 'Services de Fabrication d\'Équipements sous Pression',
    blog_basincli_kap_cta_p: 'Conception, fabrication et certification PED — équipements sous pression cat. I à IV selon EN 13445.',
    blog_basincli_kap_cta_btn: 'Contactez-nous →',

    // --- Demiryolu ---
    blog_demiryolu_kaynak_title: 'Norme de Soudage Ferroviaire EN 15085 : Wagons et Bogies | ArmaWeld Blog',
    blog_demiryolu_kaynak_title_tag: 'Norme de Soudage Ferroviaire EN 15085 : Wagons et Bogies | ArmaWeld Blog',
    blog_demiryolu_kaynak_meta_desc: 'EN 15085 norme soudage ferroviaire, niveaux certification CL1-CL4, fabrication wagons soudés, bogies, documents ECWS.',
    blog_demiryolu_kaynak_og_title: 'Norme de Soudage Ferroviaire EN 15085 : Wagons et Bogies | ArmaWeld',
    blog_demiryolu_kaynak_tag: 'Industrie Ferroviaire',
    blog_demiryolu_kaynak_h1: 'Norme de Soudage Ferroviaire EN 15085 : Guide de Certification',
    blog_demiryolu_kaynak_read: '9 min de lecture',
    blog_demiryolu_kaynak_author: 'ArmaWeld Ingénierie',
    blog_demiryolu_kaynak_breadcrumb3: 'EN 15085 Ferroviaire',
    blog_demiryolu_kaynak_s0: '<p>La norme <strong>EN 15085</strong> définit les exigences de soudage pour la fabrication et la maintenance des véhicules ferroviaires et de leurs composants. Elle s\'applique aux structures de caisses, bogies, châssis, réservoirs et tuyauteries des trains, tramways, métros et wagons de fret. La certification EN 15085 est obligatoire pour tout fabricant souhaitant livrer des composants soudés dans le secteur ferroviaire européen.</p>',
    blog_demiryolu_kaynak_s1: '<h2>Niveaux de Certification EN 15085</h2><table class="data-table"><thead><tr><th>Niveau</th><th>Portée</th><th>Exigences Clés</th></tr></thead><tbody><tr><td>CL1</td><td>Conception + Fabrication complète</td><td>IWE obligatoire, système qualité complet</td></tr><tr><td>CL2</td><td>Fabrication avec soudures de niveau CP A/B</td><td>IWS ou IWT, procédures qualifiées</td></tr><tr><td>CL3</td><td>Fabrication avec soudures de niveau CP C/D</td><td>Coordinateur de soudage interne</td></tr><tr><td>CL4</td><td>Sous-traitance simple (pas de fabrication autonome)</td><td>Référence à un CL1–CL3</td></tr></tbody></table>',
    blog_demiryolu_kaynak_s2: '<h2>Classes de Contrôle des Soudures (CP)</h2><ul><li><strong>CP A :</strong> Soudures critiques pour la sécurité — contrôle 100 % RT/UT + VT/MT/PT.</li><li><strong>CP B :</strong> Soudures importantes — contrôle aléatoire RT/UT + VT.</li><li><strong>CP C :</strong> Soudures secondaires — VT uniquement.</li><li><strong>CP D :</strong> Soudures de finition et d\'étanchéité — VT de surface.</li></ul>',
    blog_demiryolu_kaynak_s3: '<h2>Qualification des Procédures (WPQR) selon EN 15085</h2><ul><li>Qualifications selon EN ISO 15614-1 (acier), EN ISO 15614-2 (aluminium).</li><li>Les WPQR doivent être approuvés par un organisme tierce partie ou un coordinateur de soudage qualifié.</li><li>Les éléments essentiels incluent le groupe de matériaux, l\'épaisseur, le procédé et la position.</li><li>Requalification requise en cas de modification d\'un élément essentiel.</li></ul>',
    blog_demiryolu_kaynak_s4: '<h2>ECWS — European Certification for Welding on Railway Structures</h2><ul><li>L\'ECWS est le système de reconnaissance mutuelle entre organismes de certification EN 15085 en Europe.</li><li>Un certificat ECWS émis dans un pays est reconnu dans tous les pays membres.</li><li>Audit de certification initial + audit de surveillance annuel.</li><li>Audit de renouvellement tous les 3 ans.</li></ul>',
    blog_demiryolu_kaynak_s5: '<h2>Matériaux et Métaux d\'Apport en Ferroviaire</h2><table class="data-table"><thead><tr><th>Matériau</th><th>Application</th><th>Procédé Typique</th></tr></thead><tbody><tr><td>S355J2 / S420MH</td><td>Châssis de wagon</td><td>MAG (135)</td></tr><tr><td>EN AW-6005A / 6082</td><td>Caisse aluminium TGV/tramway</td><td>MIG (131) / FSW</td></tr><tr><td>X2CrNiMo 17-12-2</td><td>Réservoirs inox</td><td>TIG (141) + MAG (135)</td></tr><tr><td>S690QL</td><td>Bogies haute performance</td><td>MAG robotisé</td></tr></tbody></table>',
    blog_demiryolu_kaynak_s6: '<h2>Soudage de l\'Aluminium en Ferroviaire</h2><ul><li>Les caisses de TGV, tramways et métros modernes sont souvent en aluminium extrudé.</li><li>Procédé MIG (GMAW) avec fil ER5356 ou ER4043 selon l\'alliage de base.</li><li>Sensibilité à la porosité élevée → propreté et gaz de protection (Ar ou Ar+He) critiques.</li><li>FSW (Friction Stir Welding) pour les panneaux plans de caisse : pas de métal d\'apport, pas de fusion → faible distorsion.</li><li>Qualification soudeur aluminium selon EN ISO 9606-2.</li></ul>',
    blog_demiryolu_kaynak_s7: '<h2>Processus de Certification EN 15085 Étape par Étape</h2><ol><li>Choix du niveau de certification cible (CL1 à CL4).</li><li>Nomination d\'un coordinateur de soudage responsable (IWE/IWS selon niveau).</li><li>Qualification des procédures (WPS + WPQR).</li><li>Qualification des soudeurs selon EN ISO 9606-1/2.</li><li>Mise en place du système qualité soudage (SWPS).</li><li>Audit de pré-certification (audit blanc).</li><li>Audit de certification par l\'organisme notifié.</li><li>Délivrance du certificat + surveillance annuelle.</li></ol>',
    blog_demiryolu_kaynak_cta_h3: 'Certification et Fabrication EN 15085',
    blog_demiryolu_kaynak_cta_p: 'Accompagnement à la certification EN 15085 CL1–CL3 et fabrication de composants ferroviaires soudés.',
    blog_demiryolu_kaynak_cta_btn: 'Contactez-nous →',

    // --- Otomotiv ---
    blog_otomotiv_yan_title: 'Solutions de Soudage pour la Sous-traitance Automobile : IATF 16949 & PPAP | ArmaWeld Blog',
    blog_otomotiv_yan_title_tag: 'Solutions de Soudage pour la Sous-traitance Automobile : IATF 16949 & PPAP | ArmaWeld Blog',
    blog_otomotiv_yan_meta_desc: 'Fabrication soudée automobile, système qualité IATF 16949, processus PPAP, soudage robotisé, MAG et laser pour l\'industrie automobile.',
    blog_otomotiv_yan_og_title: 'Solutions de Soudage pour la Sous-traitance Automobile : IATF 16949 & PPAP | ArmaWeld',
    blog_otomotiv_yan_tag: 'Industrie Automobile',
    blog_otomotiv_yan_h1: 'Soudage pour la Sous-traitance Automobile : IATF 16949 et PPAP',
    blog_otomotiv_yan_read: '8 min de lecture',
    blog_otomotiv_yan_author: 'ArmaWeld Ingénierie',
    blog_otomotiv_yan_breadcrumb3: 'Automobile',
    blog_otomotiv_yan_s0: '<p>L\'industrie automobile exige des niveaux de qualité et de reproductibilité extrêmement élevés pour toutes ses pièces soudées. Les sous-traitants doivent être certifiés <strong>IATF 16949</strong>, maîtriser le processus <strong>PPAP (Production Part Approval Process)</strong> et disposer de lignes de soudage robotisées capables de garantir une répétabilité Cpk ≥ 1,67. La traçabilité complète de chaque pièce est obligatoire.</p>',
    blog_otomotiv_yan_s1: '<h2>IATF 16949 : Le Référentiel Qualité Automobile</h2><ul><li>IATF 16949 est la norme internationale du secteur automobile pour les systèmes de management de la qualité.</li><li>Elle s\'applique aux fabricants de pièces de série (OEM Tier 1, Tier 2, Tier 3).</li><li>Exigences spécifiques : APQP, PPAP, FMEA, MSA, SPC.</li><li>Audit de certification annuel par un organisme accrédité IATF.</li><li>Objectif zéro défaut en production série — ppm (parties par million) définis par le client.</li></ul>',
    blog_otomotiv_yan_s2: '<h2>PPAP : Approbation des Pièces de Production</h2><p>Le PPAP est le processus d\'approbation des pièces avant démarrage de la production en série. Les 5 niveaux de soumission PPAP :</p><ul><li><strong>Niveau 1 :</strong> Certificat de conformité (CoC) uniquement.</li><li><strong>Niveau 2 :</strong> CoC + échantillons de pièces + données de contrôle partielles.</li><li><strong>Niveau 3 :</strong> Documentation complète (standard) — le plus courant.</li><li><strong>Niveau 4 :</strong> Défini par le client.</li><li><strong>Niveau 5 :</strong> Examen complet sur site chez le fournisseur.</li></ul>',
    blog_otomotiv_yan_s3: '<h2>Soudage Robotisé en Production Automobile</h2><ul><li><strong>MAG robotisé (GMAW) :</strong> Le procédé dominant — productivité élevée, reproductibilité Cpk > 1,67.</li><li><strong>Soudage laser :</strong> Assemblage de tôles fines (< 3 mm), vitesses jusqu\'à 10 m/min.</li><li><strong>Soudage par résistance (RSW) :</strong> Points de soudure sur carrosseries — 2000+ points par véhicule.</li><li><strong>Soudage par friction-malaxage (FSW) :</strong> Pièces en aluminium (jantes, traverse de planche de bord).</li></ul>',
    blog_otomotiv_yan_s4: '<h2>Contrôle Qualité en Production Automobile</h2><ul><li><strong>Contrôle 100 % en ligne :</strong> Vision artificielle, profilomètre laser pour chaque pièce.</li><li><strong>Contrôle destructif de la soudure :</strong> Test de pelage et cisaillement selon une fréquence définie.</li><li><strong>SPC (Statistical Process Control) :</strong> Cpk ≥ 1,33 requis, Cpk ≥ 1,67 préféré.</li><li><strong>Traçabilité :</strong> Code Data Matrix ou RFID sur chaque pièce — identification et historique de fabrication.</li></ul>',
    blog_otomotiv_yan_s5: '<h2>APQP et FMEA en Soudage</h2><ul><li><strong>APQP (Advanced Product Quality Planning) :</strong> Planification qualité en 5 phases du développement à la validation série.</li><li><strong>PFMEA (Process FMEA) :</strong> Analyse des modes de défaillance du procédé de soudage — identification des causes et actions préventives.</li><li><strong>Plan de contrôle :</strong> Spécifie les paramètres, fréquences et méthodes de contrôle pour chaque opération.</li><li><strong>Réagir rapidement (QRQC) :</strong> Résolution des problèmes qualité en 24 h — méthodologie 8D.</li></ul>',
    blog_otomotiv_yan_s6: '<h2>Matériaux Avancés en Automobile</h2><table class="data-table"><thead><tr><th>Matériau</th><th>Application</th><th>Défi de Soudage</th></tr></thead><tbody><tr><td>AHSS / UHSS (> 1000 MPa)</td><td>Renforts de portes, longerons</td><td>Préchauffage, paramètres stricts</td></tr><tr><td>Aluminium 5xxx/6xxx</td><td>Capots, hayons, châssis EV</td><td>Porosité, fissuration à chaud</td></tr><tr><td>Acier galvanisé</td><td>Carrosserie, plancher</td><td>Évacuation du zinc, porosités</td></tr><tr><td>Dissimilaire acier/alu</td><td>Structures hybrides</td><td>MIG-brazage, FSW ou rivetage</td></tr></tbody></table>',
    blog_otomotiv_yan_s7: '<h2>Tendances : Électrification et Légèreté</h2><ul><li>Les véhicules électriques (BEV) accélèrent l\'adoption de l\'aluminium et des structures multi-matériaux.</li><li>Les batteries lithium-ion nécessitent un soudage laser de précision pour les interconnexions de cellules.</li><li>Le soudage hybride laser-MIG gagne du terrain pour les assemblages épais en aluminium.</li><li>La simulation numérique (FEA, CFD) est désormais intégrée dès la phase de développement PPAP.</li></ul>',
    blog_otomotiv_yan_cta_h3: 'Solutions de Soudage pour l\'Automobile',
    blog_otomotiv_yan_cta_p: 'Fabrication de composants soudés conformes IATF 16949, PPAP Niveau 3 et exigences OEM.',
    blog_otomotiv_yan_cta_btn: 'Contactez-nous →',

    // --- Isı Girdisi ---
    blog_kaynak_isi_girdisi_title: 'Calcul et Optimisation de l\'Apport Thermique en Soudage | ArmaWeld Blog',
    blog_kaynak_isi_girdisi_title_tag: 'Calcul et Optimisation de l\'Apport Thermique en Soudage | ArmaWeld Blog',
    blog_kaynak_isi_girdisi_meta_desc: 'Apport thermique soudage, formule EN ISO 1011, effet sur microstructure, distorsion et propriétés mécaniques, optimisation.',
    blog_kaynak_isi_girdisi_og_title: 'Calcul et Optimisation de l\'Apport Thermique en Soudage | ArmaWeld',
    blog_kaynak_isi_girdisi_tag: 'Procédés de Soudage',
    blog_kaynak_isi_girdisi_h1: 'Apport Thermique en Soudage : Calcul et Optimisation',
    blog_kaynak_isi_girdisi_read: '8 min de lecture',
    blog_kaynak_isi_girdisi_author: 'ArmaWeld Ingénierie',
    blog_kaynak_isi_girdisi_breadcrumb3: 'Apport Thermique',
    blog_kaynak_isi_girdisi_s0: '<p>L\'<strong>apport thermique (Heat Input)</strong> est l\'énergie thermique par unité de longueur introduite dans le joint lors du soudage. Il est l\'un des paramètres les plus critiques de la WPS : trop faible, il provoque une trempe excessive et une fragilisation de la ZAC ; trop élevé, il dégrade la résilience et augmente la distorsion. Une maîtrise précise de l\'apport thermique est essentielle pour les structures en acier haute limite élastique (HLE).</p>',
    blog_kaynak_isi_girdisi_s1: '<h2>Formule de Calcul de l\'Apport Thermique</h2><p>Selon EN ISO 1011-1, l\'apport thermique Q est calculé comme suit :</p><ul><li><strong>Q = (U × I × 60) / (v × 1000) [kJ/mm]</strong></li><li>U = tension d\'arc (V)</li><li>I = intensité de courant (A)</li><li>v = vitesse de soudage (mm/min)</li><li><strong>Facteur d\'efficacité thermique (η) :</strong> SMAW η=0,80 ; GMAW/FCAW η=0,80 ; SAW η=1,00 ; TIG η=0,60</li><li><strong>Q corrigé = Q × η</strong></li></ul>',
    blog_kaynak_isi_girdisi_s2: '<h2>Plages d\'Apport Thermique par Procédé</h2><table class="data-table"><thead><tr><th>Procédé</th><th>Plage Typique</th><th>Application</th></tr></thead><tbody><tr><td>TIG (141)</td><td>0,1 – 1,0 kJ/mm</td><td>Inox mince, titane</td></tr><tr><td>MAG (135)</td><td>0,5 – 2,5 kJ/mm</td><td>Construction générale</td></tr><tr><td>SMAW (111)</td><td>1,0 – 3,5 kJ/mm</td><td>Construction, chaudronnerie</td></tr><tr><td>SAW (121)</td><td>2,0 – 5,0 kJ/mm</td><td>Plaques épaisses, tuyaux</td></tr><tr><td>Electroslag</td><td>> 15 kJ/mm</td><td>Grandes épaisseurs, monopasse</td></tr></tbody></table>',
    blog_kaynak_isi_girdisi_s3: '<h2>Effet de l\'Apport Thermique sur la Microstructure</h2><ul><li><strong>Apport faible (&lt;1 kJ/mm) :</strong> Refroidissement rapide → martensite dans la ZAC → fragilisation → risque de fissuration à froid.</li><li><strong>Apport optimal (1–2,5 kJ/mm) :</strong> ZAC fine, bonne résilience, propriétés mécaniques conformes à la WPS.</li><li><strong>Apport élevé (>3 kJ/mm) :</strong> Croissance des grains dans la ZAC → chute de la résilience Charpy → distorsion accrue → risque de fissuration à chaud dans les aciers sensibles.</li></ul>',
    blog_kaynak_isi_girdisi_s4: '<h2>Apport Thermique et Aciers Haute Limite Élastique</h2><ul><li>Pour les aciers THLE (S460–S960), l\'apport thermique maximal est défini par le fabricant de l\'acier (fiche technique).</li><li><strong>S690QL :</strong> apport thermique max. typique 2,5–3,0 kJ/mm (à confirmer selon le fabricant).</li><li><strong>S960QL :</strong> apport thermique max. typique 1,5–2,0 kJ/mm.</li><li>Un dépassement de la limite maximale entraîne une perte irréversible des propriétés mécaniques.</li><li>L\'apport thermique doit être mesuré et enregistré pour chaque passe conformément à la WPS.</li></ul>',
    blog_kaynak_isi_girdisi_s5: '<h2>Vitesse de Refroidissement t8/5</h2><p>Le temps de refroidissement de 800°C à 500°C, noté <strong>t8/5</strong>, est le paramètre métallurgique clé :</p><ul><li>t8/5 court (5–15 s) : refroidissement rapide → risque martensitique → fragilisation.</li><li>t8/5 optimal (15–25 s) : bainite inférieure ou ferrite aciculaire → bonnes propriétés.</li><li>t8/5 long (> 30 s) : ferrite polygonale grossière → résilience dégradée.</li><li>t8/5 augmente avec l\'apport thermique, l\'épaisseur et la température de préchauffage.</li></ul>',
    blog_kaynak_isi_girdisi_s6: '<h2>Surveillance et Enregistrement de l\'Apport Thermique</h2><ul><li>Les systèmes de surveillance de l\'arc modernes (ex. : WeldCloud, HKS Arc Monitoring) enregistrent U, I et v en temps réel.</li><li>Le calcul automatique de l\'apport thermique est comparé aux limites de la WPS et une alarme est déclenchée en cas de dépassement.</li><li>Obligatoire pour les équipements sous pression (EN 13445), les structures ferroviaires (EN 15085) et les structures EN 1090.</li><li>Les enregistrements sont archivés avec le dossier de soudage.</li></ul>',
    blog_kaynak_isi_girdisi_s7: '<h2>Optimisation de l\'Apport Thermique</h2><ul><li>Ajuster simultanément U, I et v plutôt qu\'un seul paramètre.</li><li>Un passage de SMAW à MAG à fil fourré (FCAW) peut réduire l\'apport thermique de 30 % avec la même productivité.</li><li>Le soudage pulsé (MAG pulsé) offre un apport thermique réduit avec une bonne fusion.</li><li>Envisager la technique tandem pour les grandes vitesses avec faible apport thermique.</li></ul>',
    blog_kaynak_isi_girdisi_cta_h3: 'Développement WPS et Contrôle de l\'Apport Thermique',
    blog_kaynak_isi_girdisi_cta_p: 'Calcul, vérification et enregistrement de l\'apport thermique selon EN ISO 1011-1 et EN 13445.',
    blog_kaynak_isi_girdisi_cta_btn: 'Contactez-nous →',

    // --- PWHT ---
    blog_pwht_title: 'Traitement Thermique Post-Soudage (PWHT) : Détensionnement et Recuit | ArmaWeld Blog',
    blog_pwht_title_tag: 'Traitement Thermique Post-Soudage (PWHT) : Détensionnement et Recuit | ArmaWeld Blog',
    blog_pwht_meta_desc: 'PWHT traitement thermique post-soudage, détensionnement, recuit, exigences EN 13445 et ASME VIII, température et durée de traitement.',
    blog_pwht_og_title: 'Traitement Thermique Post-Soudage (PWHT) : Détensionnement et Recuit | ArmaWeld',
    blog_pwht_tag: 'Traitement Thermique & Qualité',
    blog_pwht_h1: 'Traitement Thermique Post-Soudage (PWHT) : Détensionnement',
    blog_pwht_read: '10 min de lecture',
    blog_pwht_author: 'ArmaWeld Ingénierie',
    blog_pwht_breadcrumb3: 'PWHT',
    blog_pwht_s0: '<p>Le <strong>PWHT (Post Weld Heat Treatment — Traitement Thermique Post-Soudage)</strong> consiste à porter le composant soudé à une température spécifique et à le refroidir de manière contrôlée. Objectifs : éliminer les contraintes résiduelles de soudage, stabiliser la microstructure et diffuser l\'hydrogène pour supprimer le risque de fissuration à froid.</p>',
    blog_pwht_s1: '<h2>Pourquoi Réaliser un PWHT ?</h2><ul><li><strong>Détensionnement :</strong> Les contraintes résiduelles de traction peuvent atteindre 50 à 80 % de la limite d\'élasticité. Le PWHT les réduit jusqu\'à 80 %.</li><li><strong>Diffusion de l\'hydrogène :</strong> L\'hydrogène diffusible responsable de la fissuration différée s\'échappe pendant le traitement.</li><li><strong>Amélioration de la résilience en ZAC :</strong> La ZAC durcie est revenue ; les valeurs Charpy s\'améliorent.</li><li><strong>Stabilité dimensionnelle :</strong> Déformation en service évitée.</li><li><strong>Résistance à la corrosion :</strong> Prévention de la sensibilisation des aciers inoxydables.</li></ul>',
    blog_pwht_s2: '<h2>Quand le PWHT est-il Obligatoire ?</h2><table class="data-table"><thead><tr><th>Norme</th><th>Exigence PWHT</th></tr></thead><tbody><tr><td>EN 13445 (équipement sous pression)</td><td>Acier au carbone t > 35 mm ; faiblement allié t > 19 mm</td></tr><tr><td>EN 13480 (tuyauterie de process)</td><td>P-No 1 : 19 mm ; P-No 4–6 : 13 mm</td></tr><tr><td>ASME VIII Div 1</td><td>Acier au carbone t > 38 mm</td></tr></tbody></table>',
    blog_pwht_s3: '<h2>Température et Durée du PWHT</h2><table class="data-table"><thead><tr><th>Classe d\'Acier</th><th>Température (°C)</th><th>Règle de Durée</th></tr></thead><tbody><tr><td>P-No 1 (S235, S355)</td><td>580–620</td><td>1 h / 25 mm, min. 30 min</td></tr><tr><td>P-No 4 (2,25Cr-1Mo)</td><td>680–720</td><td>1 h / 25 mm</td></tr><tr><td>P-No 6 (12–13Cr martensitique)</td><td>720–780</td><td>Minimum 2 h</td></tr><tr><td>P-No 8 (304L/316L)</td><td>1010–1100 (mise en solution)</td><td>Selon l\'épaisseur</td></tr></tbody></table><div class="callout"><p><strong>S690QL et S960QL :</strong> Le PWHT est généralement <strong>INTERDIT</strong> pour ces aciers QT. Dépasser la température de revenu réduit irréversiblement la limite d\'élasticité.</p></div>',
    blog_pwht_s4: '<h2>Vitesses de Chauffage et de Refroidissement</h2><ul><li><strong>Vitesse de chauffage (au-dessus de 300°C) :</strong> Max. 220°C/h × (25 / t)</li><li><strong>Tolérance de température de maintien :</strong> ±20°C</li><li><strong>Vitesse de refroidissement (au-dessus de 300°C) :</strong> Max. 275°C/h × (25 / t)</li><li><strong>En dessous de 300°C :</strong> Refroidissement libre à l\'air</li></ul>',
    blog_pwht_s5: '<h2>Méthodes de Chauffage</h2><ul><li><strong>Four :</strong> Le plus uniforme ; idéal pour les pièces petites et moyennes.</li><li><strong>Induction locale :</strong> Courant pour les soudures circonférentielles de tuyauterie.</li><li><strong>Couverture résistive :</strong> Économique pour les soudures locales.</li><li><strong>Chalumeau gaz :</strong> Réparations sur site ; contrôle de température difficile.</li></ul>',
    blog_pwht_s6: '<h2>Positionnement des Thermocouples</h2><ul><li>Minimum 2 thermocouples (contrôle entrée/sortie).</li><li>Épaisseur > 50 mm : thermocouples séparés sur les surfaces intérieure et extérieure.</li><li>Tous les enregistrements température-temps conservés (10 ans).</li></ul>',
    blog_pwht_s7: '<h2>Largeur de Bande de Chauffage Local</h2><ul><li><strong>Bande de chauffage :</strong> 5 × R<sub>i</sub> × t</li><li><strong>Bande de maintien :</strong> Moitié intérieure de la bande de chauffage.</li><li><strong>Bande de contrôle du gradient :</strong> Zone isolée de 2,5 × R<sub>i</sub> × t au-delà de la bande de chauffage.</li></ul>',
    blog_pwht_s8: '<h2>Erreurs Fréquentes</h2><ul><li>Durée de maintien insuffisante.</li><li>Refroidissement trop rapide.</li><li>Thermocouples absents ou mal positionnés.</li><li>Largeur de bande insuffisante lors du chauffage local.</li><li>Application du PWHT à S690QL / S960QL (INTERDIT).</li></ul><h2>Vérification Post-PWHT</h2><ul><li>Essai de dureté (HV10) : dans les limites de la WPS ?</li><li>END : PT/MT pour nouvelles fissures.</li><li>Contrôle dimensionnel : distorsion survenue ?</li></ul><div class="callout"><p><strong>Périmètre ArmaWeld :</strong> PWHT en four pour pièces jusqu\'à 8 m × 3 m × 3 m. Diagrammes de procédé et enregistrements de température selon EN 13445 et ASME VIII.</p></div>',
    blog_pwht_cta_h3: 'Services PWHT et Détensionnement',
    blog_pwht_cta_p: 'Support ingénierie pour la planification et l\'exécution du traitement thermique post-soudage.',
    blog_pwht_cta_btn: 'Contactez-nous →'

  });

